INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4165', 'spa', 'Fundición, obra de metal fundido; masa compactada', 'Sustantivo que designa la fundición de metal o la obra hecha con metal fundido, y por extensión una masa compactada en un cuerpo sólido. En 1 Reyes describe la obra en bronce de Salomón para el templo: el mar de bronce y las diez bases eran cada una «una sola fundición», hechas de una sola colada de metal (7:23, 37). Job lo usa metafóricamente para los terrones de polvo apretados entre sí (38:38). El término enfatiza la construcción sólida y unificada lograda mediante fundición o compresión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4170', 'spa', 'Trampa, lazo; cebo de cazador usado literal y figuradamente para todo lo que atrapa hacia la ruina o el pecado', 'Trampa, lazo; cebo de cazador usado literal y figuradamente para todo lo que atrapa hacia la ruina o el pecado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4171', 'spa', 'Intercambiar, sustituir o reemplazar; en Nifal, ser cambiado: trocar una cosa por otra, a menudo con graves consecuencias.', 'Intercambiar, sustituir o reemplazar; en Nifal, ser cambiado: trocar una cosa por otra, a menudo con graves consecuencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4172a', 'spa', 'Temor, pavor, terror; hechos portentosos o espectáculos sobrecogedores; el Temible (epíteto divino)', 'Sustantivo que expresa todo el espectro del temor tal como irradia desde Dios. En su sentido más frecuente, denota el pavor que cae sobre las criaturas: el ''temor y terror'' impuesto a todos los animales tras el Diluvio (Gén 9:2), o el pavor que precede a Israel en la conquista (Deut 11:25). Modificado por ''grande'', pasa a referirse a los hechos aterradores mismos: las señales portentosas del Éxodo (Deut 4:34; 26:8). En el Salmo 76:11 se convierte en título divino: Dios es ''el Temible'', epíteto en el que la emoción abstracta cristaliza como nombre de Dios mismo. Malaquías indaga el corazón relacional de esta palabra: ''Si soy señor, ¿dónde está mi temor?'' (Mal 1:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4173', 'spa', 'Trillo, implemento pesado para separar el grano de la paja', 'Sustantivo que designa el trillo, un implemento agrícola pesado usado para separar el grano de la paja. Estos trillos, con piedras afiladas en la parte inferior, eran arrastrados sobre el grano cosechado por bueyes. Cuando Arauna ofreció su era a David para un altar, incluyó sus trillos como leña para el sacrificio (2 Samuel 24:22, 1 Crónicas 21:23). Isaías emplea la imagen proféticamente, prometiendo que Israel se convertirá en un trillo afilado para trillar montañas (41:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4174', 'spa', 'Bajada, pendiente, declive; inclinación descendente o rasgo topográfico empinado, también figuradamente de obra colgante', 'Este sustantivo designa una bajada o pendiente empinada, típicamente como accidente geográfico por el cual los ejércitos persiguen o las aguas se precipitan. La bajada de Bet-horón (Jos 10:11) es donde los granizos golpearon a los amorreos en fuga, y la bajada cerca de Sebarim (Jos 7:5) marca la retirada de Israel tras Hai. Miqueas 1:4 compara las montañas disolviéndose como agua derramada por una pendiente. En 1 Reyes 7:29, el término adquiere un sentido inusual de ''obra colgante'' en las bases de bronce. El español bajada captura con claridad el significado geográfico principal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4175', 'spa', 'Lluvia temprana, lluvia otoñal al inicio de la temporada de siembra', 'Sustantivo que designa la lluvia temprana u otoñal que cae en Israel al comienzo del año agrícola (octubre-noviembre). Esta lluvia crucial ablanda la tierra para el arado y permite la germinación de las semillas. Joel promete que Dios restaurará la lluvia temprana como señal de bendición renovada (2:23, mencionada dos veces). El salmista describe la lluvia temprana como una bendición divina que transforma la tierra (84:6). El término enfatiza las lluvias estacionales esenciales para la prosperidad agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4176', 'spa', 'Moré (topónimo: ''maestro'' o ''el que da oráculos'')', 'Nombre de lugar que significa «maestro» o «el que da oráculos», que marca dos sitios sagrados. La «encina de Moré» (o «encina del maestro») cerca de Siquem fue donde Abraham se detuvo por primera vez en Canaán y recibió la promesa de Dios (Génesis 12:6, Deuteronomio 11:30). El «collado de Moré» estaba cerca de la llanura de Jezreel, donde acamparon las fuerzas de Gedeón (Jueces 7:1), probablemente el Pequeño Hermón. Ambos sitios eran aparentemente lugares antiguos donde se recibía instrucción divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4177', 'spa', 'Navaja, instrumento cortante afilado para afeitar o rasurar', 'Sustantivo que designa una navaja o cuchilla afilada usada para cortar el cabello. El término aparece exclusivamente en contextos nazareos, en la fórmula «no pasará navaja sobre su cabeza». Esto se aplica a Sansón desde antes de nacer (Jueces 13:5, 16:17) y a Samuel (1 Samuel 1:11). La prohibición de la navaja era una marca distintiva de la consagración nazarea a Dios, donde el cabello sin cortar simbolizaba dedicación y fortaleza. Violar esta prohibición, como hizo Sansón, significaba romper el voto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4180', 'spa', 'posesión, herencia; lo que pertenece legítimamente a alguien o a un grupo', 'Sustantivo que designa una posesión o herencia: aquello que legítimamente pertenece a alguien o a un grupo. Isaías profetiza que Babilonia se convertirá en «posesión del erizo» (14:23), un páramo desolado. Abdías declara que la casa de Jacob poseerá «sus posesiones», reclamando lo que les corresponde por derecho (17). Job habla metafóricamente de «las posesiones de mi corazón», es decir, sus anhelos más profundos (17:11). El término subraya la titularidad legítima o la herencia prometida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4181', 'spa', 'Posesión o herencia, especialmente tierra otorgada por Dios como patrimonio nacional permanente.', 'Este sustantivo femenino designa una posesión o herencia, referida casi siempre a la tierra concedida como dotación divina. En Éxodo 6:8, Dios promete entregar a Israel la tierra de Canaán como מוֹרָשָׁה, una posesión permanente y pactada. Deuteronomio 33:4 aplica el término de manera singular a la Torá misma: «Moisés nos ordenó la ley, heredad de la congregación de Jacob». En Ezequiel, la palabra adquiere un tono de disputa, cuando las naciones vecinas reclaman la tierra de Israel como su מוֹרָשָׁה (Ez 25:4, 10; 36:2, 5), lo que provoca reprensión profética. El término lleva consigo el peso teológico de una propiedad autorizada divinamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4185', 'spa', 'Apartarse, retirarse o remover; en Hifil, hacer que algo se aleje o que cese. Describe el acto de alejarse o ser quitado de una posición fija. En la r', 'Apartarse, retirarse o remover; en Hifil, hacer que algo se aleje o que cese. Describe el acto de alejarse o ser quitado de una posición fija. En la raíz Qal es intransitivo — la columna de nube ''no se apartaba'' de delante del pueblo (Éx 33:11), y a Josué se le dice que la Torá no ''se aparte'' de su boca (Jos 1:8). En el Hifil, el verbo puede permanecer intransitivo (Job 23:12, ''no me he apartado del mandamiento'') o volverse causativo: Dios declara ''quitaré'' la iniquidad de la tierra en un solo día (Zac 3:9). La palabra tiene peso teológico: cuando algo ''no se aparta,'' señala permanencia, fidelidad al pacto o presencia divina inquebrantable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4186', 'spa', 'Asiento o lugar donde sentarse; asamblea; morada, asentamiento o habitación; también el acto o período de habitar', 'Asiento o lugar donde sentarse; asamblea; morada, asentamiento o habitación; también el acto o período de habitar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4187', 'spa', 'Musi, levita, hijo de Merari; ancestro del clan musita dentro de la tribu de Leví.', 'Musi fue hijo de Merari y nieto de Leví, lo que lo convierte en fundador de uno de los dos subclanes principales de los meraritas (el otro es el de Mahli). Aparece de manera constante en las listas genealógicas que trazan las familias levíticas (Éx 6:19; Nm 3:20; 1 Cr 6:19, 47; 23:21, 23; 24:26, 30). La Septuaginta transcribe su nombre de diversas formas, como Omousi o Mousi. Sus descendientes desempeñaron funciones importantes en el servicio del tabernáculo y del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4191', 'spa', 'Morir, estar muerto; (Hifil) matar, dar muerte; (Hofal) ser ejecutado; (participio) los muertos; (infinitivo) muerte', 'Una de las palabras más elementales de las Escrituras, este verbo hebreo (מוּת) abarca todo el arco de la mortalidad. En la conjugación Qal describe el morir en todas sus modalidades —natural, violenta y judicial—, mientras que el Hifil causativo significa ''matar'' y el Hofal pasivo ''ser ajusticiado''. La fórmula enfática מוֹת יוּמָת (''de cierto morirá'') se convirtió en el giro característico del derecho pactual, escuchado por primera vez en el Edén (Gn 2:17) y repetido a lo largo de los códigos legales de la Torá. El participio funciona como sustantivo para ''los muertos'' o ''el cadáver'', y el infinitivo constructo sirve como nombre abstracto ''muerte''. A lo largo de sus 840 apariciones, מוּת traza la teología bíblica de la vida y la muerte desde Génesis hasta Malaquías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4192', 'spa', 'término musical o litúrgico, posiblemente «sobre la muerte» o nombre de una melodía', 'Una enigmática anotación musical o litúrgica que aparece en los títulos de ciertos salmos. La frase «al-mut labben» en el Salmo 9:1 tiene un significado incierto: podría significar «sobre la muerte del hijo», o quizá sea el nombre de una melodía o modo musical. El Salmo 48:14 emplea una forma relacionada. Los intérpretes antiguos ya luchaban con esta expresión, y los estudiosos modernos siguen divididos. Este término nos recuerda que parte del vocabulario técnico musical del culto del antiguo Israel se ha perdido, aunque los salmos mismos conservan toda su fuerza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4194', 'spa', 'Muerte: el acto de morir, el estado de estar muerto, la muerte personificada como potencia cósmica, y la muerte como pena o parámetro de comparación', 'Māvet es mucho más que un término clínico para el cese biológico. En la Escritura hebrea funciona simultáneamente como evento, estado, potencia y castigo. Como evento, marca el instante en que la vida se extingue (Dt 19:6); como estado, nombra el ámbito sombrío desde el cual el salmista clama por liberación (Sal 116:15); como fuerza personificada, se convierte en socio de pacto para los impíos (Is 28:15) y en rival del amor mismo (Cnt 8:6). El plural מוֹתֵי en Ez 28:10 —''muertes de los incircuncisos''— insinúa que la muerte puede multiplicarse, un plural intensivo o violento que trasciende con creces la mera biología.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4195', 'spa', 'abundancia, exceso; superioridad, ventaja', 'Sustantivo con dos acepciones relacionadas: abundancia o excedente, y superioridad o ventaja. En Proverbios aparece dos veces en contraste con la carencia: el trabajo arduo conduce a la abundancia, pero la precipitación solo lleva a la pobreza (14:23; 21:5). Eclesiastés lo emplea filosóficamente para cuestionar si el ser humano tiene alguna ventaja real sobre los animales (3:19). El término puede denotar tanto un superávit material como una superioridad cualitativa, enfatizando siempre el «más que» o «mejor que».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4196', 'spa', 'Altar: instalación cúltica elevada para ofrecer sacrificios, derivada de la raíz זָבַח (''degollar, sacrificar'')', 'Mizbēaḥ designa el altar como pieza litúrgica central del culto israelita, derivado de la raíz זָבַח (''degollar, sacrificar''). Con más de 400 apariciones, traza el arco completo de la historia cultual de Israel: desde el altar de Noé tras el diluvio (Gn 8:20), pasando por los altares patriarcales, hasta los elaborados altares de bronce y oro del Tabernáculo y el Templo, y finalmente la destrucción polémica de los altares idolátricos bajo Josías. El cognado árabe maḏbaḥ (''lugar de degüello'') conserva la misma lógica etimológica. Las traducciones muestran una consistencia casi perfecta: español altar, francés autel, alemán Altar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4199', 'spa', 'Miza (nombre propio: posiblemente «temor» o «terror»)', 'Nombre propio perteneciente a un nieto de Esaú a través de Reuel y Basemat. Miza aparece en las genealogías edomitas como uno de los descendientes de Esaú que llegó a ser jefe de clan en Edom (Génesis 36:13, 17; 1 Crónicas 1:37). El nombre posiblemente deriva de una raíz que significa temor o terror. Como muchos nombres edomitas conservados en Génesis, marca el cumplimiento de la promesa de Dios de que Esaú también sería padre de naciones, aunque distinto de la línea del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4201', 'spa', 'Jamba, poste de puerta — el marco vertical lateral de una puerta o abertura de portón. Su aparición más memorable es en la narrativa de la Pascua, don', 'Jamba, poste de puerta — el marco vertical lateral de una puerta o abertura de portón. Su aparición más memorable es en la narrativa de la Pascua, donde se ordenó a los israelitas untar la sangre del cordero en las jambas y el dintel (Éx 12:7, 22–23), una imagen que se volvió fundacional para la identidad judía. La palabra también figura en el mandamiento de escribir las palabras de Dios en las jambas de la casa (Dt 6:9; 11:20), dando origen a la tradición posterior de la mezuzá. En la arquitectura del templo, describe los postes del templo de Salomón (1 R 6:31, 33) y del santuario visionario de Ezequiel (Ez 41:21; 43:8; 45:19; 46:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4205', 'spa', 'herida, llaga; lesión que requiere tratamiento', 'Sustantivo que designa una herida o llaga, específicamente una que requiere tratamiento o drenaje de materia infectada. Aparece exclusivamente en textos proféticos como metáfora de la condición espiritual y nacional de Israel y Judá. Jeremías lamenta que no hay medicina sanadora para la herida (30:13). Oseas afirma dos veces que la llaga de Israel no puede ser curada, ni siquiera por el poder de Asiria (5:13). El término subraya no solo la lesión, sino un daño purulento e incurable que ningún remedio humano puede resolver.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4207b', 'spa', 'Garfios o trinchantes sacrificiales; horquillas de tres puntas para manipular las ofrendas sobre el altar', 'La מִזְלָגָה (siempre en plural en la Biblia hebrea) designa garfios o trinchantes grandes empleados en el servicio sacrificial. Estos utensilios formaban parte del equipamiento del altar del tabernáculo (Ex 27:3; 38:3; Nm 4:14) y posteriormente del templo de Salomón (1 Cr 28:17; 2 Cr 4:16). Su aparición constante junto a tazones, paletas y braseros los identifica como implementos estándar del culto para el manejo de los holocaustos. El español garfios subraya su función de enganchar y voltear la carne sobre el fuego del altar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4209', 'spa', 'Propósito o plan (neutral); discreción o prudencia (positivo, en Proverbios); maquinación o intriga perversa (negativo, en Salmos/Profetas). El sustan', 'Propósito o plan (neutral); discreción o prudencia (positivo, en Proverbios); maquinación o intriga perversa (negativo, en Salmos/Profetas). El sustantivo מְזִמָּה es una de las palabras con mayor flexibilidad moral del hebreo, capaz de describir la sabiduría piadosa y la astucia malévola con igual facilidad. En Proverbios, se sitúa junto al conocimiento y al entendimiento como una virtud intelectual positiva: la ''discreción'' que protege al joven de la insensatez (Pr 1:4; 2:11; 3:21). Pero en los Salmos y los Profetas, la misma palabra se oscurece hacia ''maquinaciones perversas'' e ''intrigas malvadas'' tramadas contra los justos (Sal 10:2; 21:11; 37:7). El terreno neutral intermedio aparece cuando describe los propósitos soberanos de Dios (Job 42:2; Jer 23:20; 51:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4210', 'spa', 'mizmor — salmo; término técnico de los encabezados para una composición musical cantada con acompañamiento instrumental.', 'mizmor — salmo; término técnico de los encabezados para una composición musical cantada con acompañamiento instrumental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4211', 'spa', 'Podaderas; herramientas curvas para podar vides, símbolo profético de la transformación entre guerra y paz', 'Implementos agrícolas utilizados para podar vides y otras plantas, que ocupan un lugar destacado en la imaginería profética sobre la guerra y la paz. Isaías y Miqueas vislumbran un futuro en el que las naciones «forjarán sus espadas en rejas de arado y sus lanzas en podaderas» (Isaías 2:4; Miqueas 4:3), simbolizando la paz universal. Joel invierte la imagen: «forjad espadas de vuestros azadones y lanzas de vuestras podaderas» (Joel 3:10), describiendo la preparación para el juicio divino. Así, esta herramienta se convierte en un poderoso símbolo de la transformación entre la guerra y la agricultura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4212', 'spa', 'Despabiladeras; utensilios del templo para recortar o apagar las mechas del candelabro', 'La מְזַמֶּרֶת (siempre en plural) designa despabiladeras o cortamechas empleados en el mantenimiento del candelabro del templo. El inventario del templo de Salomón las enumera entre los enseres sagrados de oro (1 R 7:50; 2 Cr 4:22). Reaparecen en los relatos del saqueo babilónico, donde fueron llevadas como objetos de bronce (2 R 25:14; Jer 52:18), mientras que 2 Reyes 12:13 señala que no se fabricaron con los fondos destinados a las reparaciones del templo. La raíz זמר, en su sentido de cortar, conecta con la acción de recortar las mechas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4213', 'spa', 'Muy poco, insignificante; expresión enfática que indica cantidad o tiempo mínimos', 'Expresión intensificadora que significa «muy poco» o «una insignificancia», usada para enfatizar la brevedad del tiempo o la pequeñez de una cantidad. Isaías la emplea para subrayar cuán pronto actuará Dios: «dentro de muy poco tiempo» (Isaías 10:25; 29:17) antes de que la intervención divina transforme la situación. También describe el lastimosamente escaso remanente que sobrevivirá al juicio (Isaías 16:14; 24:6). La expresión duplicada crea un énfasis especial: no simplemente «poco», sino enfáticamente mínimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4217', 'spa', 'El este como punto cardinal; también la salida del sol, frecuentemente en la expresión ''mizraj hashemesh''.', 'El este como punto cardinal; también la salida del sol, frecuentemente en la expresión ''mizraj hashemesh''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4219', 'spa', 'Tazón, cuenco — vasija ritual para recoger y rociar sangre sacrificial o presentar ofrendas', 'Tazón, cuenco — vasija ritual para recoger y rociar sangre sacrificial o presentar ofrendas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4222', 'spa', 'Aplaudir, batir las manos en señal de gozo o triunfo', 'Verbo que significa aplaudir o batir las manos, generalmente como expresión de júbilo o exultación. El salmista invita a los ríos a aplaudir ante el Señor (98:8). Isaías profetiza que hasta los árboles del campo batirán palmas de gozo ante la restauración venidera (55:12). Ezequiel lo emplea en sentido negativo para describir el aplauso malicioso de los amonitas ante la caída de Israel (25:6). El sentido principal es la celebración gozosa, con la creación inanimada personificada uniéndose a la adoración y el regocijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4223', 'spa', 'Golpear, herir, impedir (arameo); verbo que abarca impacto físico y restricción figurada', 'Verbo arameo que significa golpear o herir, presente en las visiones apocalípticas de Daniel y en el relato de Esdras sobre los eventos del período persa. En Daniel 2:34-35, la piedra que golpea la gran imagen representa el reino de Dios destruyendo los imperios terrenales. La expresión «golpear su mano» (Daniel 4:35) significa impedir o detener a alguien en su propósito. Esdras 6:11 lo usa en el decreto que prescribe el empalamiento como castigo por violar el edicto real: el infractor será «colgado» o clavado en un madero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4225', 'spa', 'Lugar de unión, costura, juntura; punto donde se conectan los paños de cortina o las piezas del efod en la construcción del tabernáculo.', 'Este sustantivo femenino designa un punto de unión o juntura, es decir, la costura donde dos piezas de tela se conectan entre sí. Aparece exclusivamente en las narrativas del tabernáculo en Éxodo, describiendo tanto la unión de los conjuntos de cortinas (Éx 26:4-5; 36:11-12, 17) como el acoplamiento de las hombreras del efod (Éx 28:27; 39:20). El término pertenece al vocabulario arquitectónico meticuloso de la fuente sacerdotal, y cada aparición refiere al acto preciso de ensamblar los elementos sagrados del santuario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4227', 'spa', 'Plancha, sartén o comal para hornear ofrendas de cereal; también plancha de hierro usada simbólicamente como muro de asedio', 'La מַחֲבַת es una superficie plana de cocción empleada principalmente para preparar la ofrenda de cereal (minjá). Levítico distingue las ofrendas hechas en sartén de las preparadas en olla honda (2:5; 6:14; 7:9), y 1 Crónicas 23:29 incluye las tortas de sartén entre las provisiones levíticas. En Ezequiel 4:3, una מַחֲבַת de hierro cumple un propósito llamativamente distinto: el profeta la coloca como muro simbólico entre él y una maqueta de Jerusalén sitiada. El español sartén y el francés poêle apuntan a una superficie plana de cocción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4229a', 'spa', 'Borrar, limpiar; borrar pasando la mano o un paño sobre una superficie, ya sea enjugando lágrimas, borrando nombres o destruyendo seres vivos de la ti', 'Borrar, limpiar; borrar pasando la mano o un paño sobre una superficie, ya sea enjugando lágrimas, borrando nombres o destruyendo seres vivos de la tierra');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4234', 'spa', 'Danza, baile; actividad comunitaria y gozosa asociada con la adoración, la celebración y la reversión del duelo.', 'Sustantivo masculino que designa la danza o el baile, frecuentemente emparejado con instrumentos musicales como el pandero (תֹּף) y presentado como la antítesis del luto. Los Salmos celebran la danza como acto de alabanza al SEÑOR (Sal 149:3; 150:4), y la transformación del luto en danza marca la liberación divina (Sal 30:11). Jeremías profetiza la restauración de la danza gozosa de Israel (Jer 31:4, 13), mientras que Lamentaciones 5:15 lamenta su cesación. La forma constructa hebrea מְחוֹל aparece tanto en contextos de adoración como de festividad comunitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4236', 'spa', 'Visión profética recibida en estado extático; experiencia visionaria de revelación divina', 'Término para la experiencia visionaria, particularmente en el estado profético extático. Describe cómo «la palabra del Señor vino a Abram en visión» (Génesis 15:1), los oráculos de Balaam recibidos como «visión del Todopoderoso» (Números 24:4, 16) y las falsas visiones de los profetas mentirosos (Ezequiel 13:7). La palabra enfatiza la naturaleza visual y reveladora de la experiencia, algo visto y no meramente oído, aunque frecuentemente acompañado de discurso divino. Marca momentos en los que la frontera entre lo divino y lo humano se hace visible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4237', 'spa', 'Ventana, abertura para ver y dar luz; elemento arquitectónico del templo de Salomón', 'Elemento arquitectónico que proporciona luz y visibilidad, presente únicamente en la descripción de la construcción del templo de Salomón. La frase «ventana frente a ventana» o «luz frente a luz» (1 Reyes 7:4-5) describe la disposición de las aberturas en las estructuras palaciegas, creando un patrón de iluminación simétrica. El término enfatiza la función de la ventana como «lugar para ver» o fuente de luz, más que como simple abertura en un muro, subrayando así la intención estética y funcional del diseño salomónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4241', 'spa', 'Preservación de vida, sustento, medio de subsistencia; también carne viva en diagnóstico levítico.', 'Derivado de la raíz חָיָה («vivir»), este sustantivo designa todo aquello que sostiene, restaura o manifiesta la vida. José reconoce el propósito de Dios al enviarlo a Egipto «para preservación de vida» (Gn 45:5), y Esdras ora por «un poco de alivio» en medio de la servidumbre (Esd 9:8-9). En las leyes sacerdotales sobre enfermedades cutáneas, adquiere un sentido médico preciso: la carne viva o en carne viva visible dentro de una lesión (Lv 13:10, 24). Una tercera línea semántica es el sustento material, como cuando los madianitas no dejaron «sustento» en Israel (Jue 6:4) o Micaía ofrece a un levita «tu mantenimiento» (Jue 17:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4242', 'spa', 'Precio, costo: el pago o valor ofrecido por bienes, tierras o, en sentido figurado, por cosas intangibles como la sabiduría o las personas.', 'Precio, costo: el pago o valor ofrecido por bienes, tierras o, en sentido figurado, por cosas intangibles como la sabiduría o las personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4244', 'spa', 'Majla: hija de Zelofehad; también nombre galaadita', 'Majla es conocida sobre todo como una de las cinco hijas de Zelofehad que valientemente solicitaron a Moisés una herencia en la tierra, dado que su padre había muerto sin hijos varones (Nm 27:1). Su caso estableció un precedente decisivo en la legislación de herencias de Israel. El nombre aparece también una vez en una genealogía galaadita (1 Cr 7:18), donde el género podría ser masculino. La Septuaginta lo traduce de diversas formas, como Maala y Maela. Su etimología posiblemente se relaciona con una raíz que significa ''enfermedad'' o ''debilidad''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4245b', 'spa', 'enfermedad, dolencia', 'Término general para referirse a enfermedad o dolencia, que aparece en contextos de protección y juicio divinos. Dios promete a Israel: «No traeré sobre ti ninguna de las enfermedades que traje sobre los egipcios, porque yo soy el Señor, tu sanador» (Éxodo 15:26). Por el contrario, la enfermedad figura entre las maldiciones por quebrantar el pacto. La oración de Salomón en la dedicación del templo reconoce que la dolencia, junto con otras plagas, puede impulsar al pueblo a buscar a Dios (1 Reyes 8:37, 2 Crónicas 6:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4246', 'spa', 'Danza, danza en corro; baile comunitario gozoso, frecuentemente para celebrar victorias militares o adorar a Dios.', 'Este sustantivo femenino designa una danza o baile en corro realizado en celebración comunitaria, frecuentemente tras una victoria militar o en contexto de adoración. Miriam guio a las mujeres con panderos y danzas después del cruce del mar Rojo (Éx 15:20); la hija de Jefté salió danzando al encuentro de su padre victorioso (Jue 11:34); y las mujeres de Israel cantaron y danzaron para celebrar el triunfo de David (1 S 18:6). El Cantar de los Cantares emplea el término para evocar belleza y gracia (7:1). La palabra conserva siempre una cualidad festiva y cinética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4248', 'spa', 'Majlón, hijo de Elimélec y primer esposo de Rut', 'Uno de los dos hijos de Noemí que se casaron con mujeres moabitas durante la estancia de la familia en Moab. Su muerte prematura, junto con la de su hermano Quelión, dejó viudas a Rut y a Orfa, y preparó el escenario para la lealtad extraordinaria de Rut hacia Noemí y su posterior matrimonio con Booz. Su nombre aparece en el marco genealógico que establece el derecho legal de Rut a la redención y el papel de Booz como pariente redentor (Rut 4:9-10). Aunque su vida fue breve, su muerte se convirtió en el punto decisivo de una de las historias más hermosas de fidelidad y redención en las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4249', 'spa', 'Mahli — nombre personal levítico; hijo de Merari y ancestro de un importante clan levítico', 'Mahli (מַחְלִי) es el nombre de dos levitas en el Antiguo Testamento. El más destacado es hijo de Merari y nieto de Leví, fundador de uno de los principales subclanes levíticos. Los mahlitas eran responsables de transportar los bastidores, travesaños, columnas y basas del tabernáculo durante la marcha por el desierto (Núm 3:20, 33; 4:29-33). Las genealogías de 1 Crónicas trazan cuidadosamente la línea de Mahli (1 Cr 6:4, 29; 23:21, 23; 24:26-28), señalando que sus hijos se casaron con sus primas porque una rama carecía de hijas. Un segundo Mahli aparece en 1 Crónicas 6:32; 23:23 como hijo de Musi, lo que lo convierte en sobrino y homónimo del primero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4256', 'spa', 'División, turno; unidad organizativa especialmente de sacerdotes y levitas, o porción de tierra asignada a una tribu', 'División, turno; unidad organizativa especialmente de sacerdotes y levitas, o porción de tierra asignada a una tribu');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4261', 'spa', 'Deseo, deleite; algo precioso o atesorado; se usa tanto para personas amadas entrañablemente como para posesiones valiosas.', 'Deseo, deleite; algo precioso o atesorado; se usa tanto para personas amadas entrañablemente como para posesiones valiosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4264', 'spa', 'Campamento: lugar temporal de tiendas, especialmente el campamento de Israel en el desierto; por metonimia, el ejército acampado allí', 'Maḥaneh es la palabra que define la identidad de Israel en el desierto: un pueblo en marcha, habitando en tiendas, organizado alrededor del tabernáculo en el centro del campamento. Desde Éxodo hasta Números, el campamento es un espacio sagrado con estrictas normas de pureza: el impuro debe ser enviado ''fuera del campamento'' (Nm 5:2-3), y Dios mismo camina ''en medio del campamento'' (Dt 23:14). El término se extiende naturalmente a los campamentos militares donde los ejércitos acampan antes de la batalla (Jos 10:5; Jue 7:15), y ocasionalmente el lugar físico cede paso a las personas mismas: el ''campamento'' que tiembla es el ejército que tiembla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4266', 'spa', 'Mahanaim: ciudad en Galaad que significa ''dos campamentos'', vinculada al encuentro angélico de Jacob.', 'Mahanaim: ciudad en Galaad que significa ''dos campamentos'', vinculada al encuentro angélico de Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4268', 'spa', 'Refugio o amparo, especialmente de Dios como el refugio protector de su pueblo en los Salmos y los Profetas. Derivado de la raíz que significa ''refugi', 'Refugio o amparo, especialmente de Dios como el refugio protector de su pueblo en los Salmos y los Profetas. Derivado de la raíz que significa ''refugiarse,'' este sustantivo designa un lugar de protección o resguardo. Si bien puede referirse a refugio físico contra la lluvia y la tormenta (Is 4:6; 25:4; Job 24:8), su uso predominante en las Escrituras es teológico: Dios mismo como el refugio de su pueblo. Los Salmos están saturados de esta palabra — ''mi refugio'' aparece repetidamente como confesión personal de confianza (Sal 62:7–8; 71:7; 73:28; 91:2, 9). Isaías advierte contra un ''refugio de mentiras'' (Is 28:15, 17), contrastando la falsa seguridad con el verdadero amparo que solo se encuentra en el Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4270', 'spa', 'Carencia, necesidad, pobreza: la condición de ser deficiente en recursos materiales o necesidades básicas.', 'Carencia, necesidad, pobreza: la condición de ser deficiente en recursos materiales o necesidades básicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4272', 'spa', 'Golpear de lleno, destrozar, aplastar o herir gravemente; término poético para golpes devastadores militares o divinos', 'Golpear de lleno, destrozar, aplastar o herir gravemente; término poético para golpes devastadores militares o divinos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4274', 'spa', 'Talla, labrado; piedra labrada o de cantera', 'Sustantivo que designa la acción de labrar o tallar, aplicado específicamente a las piedras labradas o de cantera preparadas para la construcción. Aparece únicamente en la expresión ''piedras labradas'' (literalmente ''piedras de talla'') en contextos de reparación del templo. Tanto los pasajes de 2 Reyes (12:12; 22:6) como el paralelo de Crónicas (34:11) mencionan la compra de piedras labradas junto con madera para restaurar el templo. El término destaca piedras deliberadamente cortadas y moldeadas, distinguiéndolas de las piedras sin desbastar, señal de construcción de calidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4276', 'spa', 'Mitad — una de dos porciones iguales, usada para el impuesto del medio siclo, el reparto de botín y las medias tribus. Sustantivo femenino que signifi', 'Mitad — una de dos porciones iguales, usada para el impuesto del medio siclo, el reparto de botín y las medias tribus. Sustantivo femenino que significa ''mitad'' o ''una mitad de un todo,'' que siempre aparece en estado constructo o con sufijos para indicar la mitad de una cantidad especificada. Su uso más célebre es el impuesto del medio siclo del censo: cada israelita de veinte años en adelante contribuía un מַחֲצִית הַשֶּׁקֶל como ''dinero de rescate'' (Éx 30:13, 15; 38:26). También rige la división del botín de guerra en Números 31 — mitad para los soldados, mitad para la congregación (Nm 31:29, 30, 42, 47) — y designa las medias tribus de Manasés en las asignaciones territoriales (Jos 21:25; 1 Cr 6:46).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4279', 'spa', 'Mañana, el día siguiente; también se usa idiomáticamente para expresar ''en el futuro'' o ''con el tiempo''.', 'Mañana, el día siguiente; también se usa idiomáticamente para expresar ''en el futuro'' o ''con el tiempo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4283', 'spa', 'El día siguiente, el mañana; sustantivo temporal que designa el día posterior a un evento de referencia', 'El día siguiente, el mañana; sustantivo temporal que designa el día posterior a un evento de referencia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4284', 'spa', 'Pensamiento, plan, maquinación, designio; actividad cognitiva que abarca desde la reflexión silenciosa hasta el propósito deliberado, la conspiración ', 'Pensamiento, plan, maquinación, designio; actividad cognitiva que abarca desde la reflexión silenciosa hasta el propósito deliberado, la conspiración hostil y el diseño artístico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4285', 'spa', 'Lugar oscuro o tinieblas; usado poéticamente para escondites, el sepulcro, el Seol y lo secreto', 'Sustantivo poético que designa un lugar oscuro o una región de tinieblas, con una rica carga metafórica en los Salmos, Lamentaciones e Isaías. Puede referirse a los escondrijos de la violencia en la tierra (Sal 74:20), a las profundidades sombrías asociadas con la muerte y el Seol (Sal 88:6, 18; 143:3; Lam 3:6), o a la clandestinidad en que operan los confabuladores (Isa 29:15). Isaías 42:16 ofrece la esperanzadora inversión, prometiendo que Dios convertirá las tinieblas en luz. La palabra evoca no solo ausencia de luz, sino desolación espiritual y ocultamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4287', 'spa', 'Majat (nombre propio: posiblemente ''agarrar'' o ''asir'')', 'Nombre propio llevado por dos levitas mencionados en Crónicas. El primer Majat aparece en una lista genealógica de levitas (1 Crónicas 6:35). El segundo, o posiblemente el mismo individuo en contextos diferentes, aparece durante las reformas de Ezequías como uno de los levitas que ayudaron a consagrar el templo (2 Crónicas 29:12) y después sirvió como supervisor de las ofrendas del templo (31:13). El nombre puede derivar de una raíz que significa asir o agarrar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4288', 'spa', 'Ruina o destrucción (especialmente de necios); terror u objeto de espanto (en contextos de juicio profético)', 'Sustantivo poético que aparece casi exclusivamente en Proverbios y los profetas, con dos sentidos relacionados pero distinguibles. En la literatura sapiencial, denota la ruina como consecuencia natural de la necedad y la maldad: la boca del necio es su propia ruina (Prov 10:14; 13:3; 18:7), la pobreza es la ruina del pobre (Prov 10:15) y los malhechores enfrentan destrucción (Prov 10:29). En los textos proféticos, el énfasis se desplaza hacia el terror y el espanto: a Sion se le promete liberación del terror (Isa 54:14), Jeremías ruega a Dios que no sea terror para él (Jer 17:17) y Moab se convierte en objeto de espanto (Jer 48:39). El español distingue bien ambos matices: ''ruina'' para los contextos sapienciales, ''terror'' para los proféticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4289', 'spa', 'Brasero, incensario o platillo; recipiente ritual para transportar brasas, incienso o recortar mechas de lámparas', 'Brasero, incensario o platillo; recipiente ritual para transportar brasas, incienso o recortar mechas de lámparas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4291', 'spa', 'Alcanzar, llegar, arribar; verbo arameo usado exclusivamente en Daniel para llegar a un lugar, extenderse o sobrevenir.', 'Este verbo arameo significa alcanzar, llegar o arribar, y aparece únicamente en el libro de Daniel. Describe el gran árbol de Nabucodonosor cuya altura «alcanzaba» hasta el cielo (Dan 4:11, 20), un decreto que «sobrevino» al rey (Dan 4:24, 28), y al Anciano de Días ante quien uno «llegó» en visión (Dan 7:13). Las traducciones españolas alcanzar y llegaba captan bien la doble dimensión espacial y temporal del término: tanto la extensión física como la llegada de los tiempos señalados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4294', 'spa', 'Vara, cayado o rama; por metonimia, una tribu de Israel descendiente de un patriarca, la acepción bíblica dominante', 'Originalmente designaba un bastón o vara de madera portado por viajeros, pastores o líderes, pero adquirió su significado bíblico más frecuente mediante una vívida metonimia: así como una rama brota de un tronco, una tribu se ramifica de un ancestro patriarcal. El 73% de sus apariciones se refiere a las divisiones tribales de Israel, convirtiéndolo en el término estándar en Números y Josué para la organización nacional. La acepción concreta aparece memorablemente en la vara prodigiosa de Moisés (Éx 4:2-17) y la vara florecida de Aarón (Nm 17). En Ezequiel 19 describe ramas literales de una vid, mientras que Habacuc 3:9, 14 conserva un uso arcaico raro para implementos de adivinación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4295', 'spa', 'Hacia abajo, abajo, debajo — adverbio de dirección espacial que indica posición inferior o descenso. Derivado de la raíz נָטָה (''extender, inclinar'') ', 'Hacia abajo, abajo, debajo — adverbio de dirección espacial que indica posición inferior o descenso. Derivado de la raíz נָטָה (''extender, inclinar'') con la terminación locativa he, indicando dirección descendente, posición inferior o ''debajo.'' Frecuentemente se empareja con su antónimo מַעְלָה (''hacia arriba'') para expresar la totalidad del rango espacial. En Deuteronomio 28:43 el término se duplica dramáticamente — ''abajo, abajo'' — para representar las maldiciones del pacto de declive progresivo. Combinado con preposiciones produce expresiones como ''desde abajo'' (describiendo la base del altar del tabernáculo en Éx 27:5; 38:4) y ''raíz hacia abajo'' (Is 37:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4296', 'spa', 'Cama, lecho; mueble para dormir o recostarse; raramente un féretro fúnebre o litera real', 'Cama, lecho; mueble para dormir o recostarse; raramente un féretro fúnebre o litera real');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4301', 'spa', 'Tesoro escondido; algo oculto de gran valor, enterrado o guardado en secreto', 'En hebreo, מַטְמוֹן designa un tesoro que ha sido enterrado u ocultado, ya sea en sentido literal o figurado. El mayordomo de José asegura a los hermanos que su dinero era un tesoro escondido puesto por Dios en sus costales (Gn 43:23). Proverbios 2:4 exhorta a buscar la sabiduría como quien busca tesoros enterrados. Isaías 45:3 promete a Ciro ''tesoros de las tinieblas y riquezas de lugares secretos'', mientras Jeremías 41:8 menciona provisiones ocultas en un campo. Job 3:21 emplea la imagen de anhelar la muerte más que un tesoro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4302', 'spa', 'Plantío, plantación o lugar de siembra; usado figuradamente del pueblo de Dios como su preciado plantío', 'Sustantivo masculino que denota un plantío, plantación o el acto y lugar de plantar, presente exclusivamente en la literatura profética. Su uso más memorable es la metáfora del pueblo de Dios como «plantío de Jehová» (Isa 60:21; 61:3), donde la imagen transmite cuidado divino, cultivo intencionado y esperanza de fecundidad. Ezequiel lo emplea para imágenes agrícolas literales de trasplante de vides (Ez 17:7; 31:4) y un prometido «plantío de renombre» (Ez 34:29). Miqueas 1:6 lo usa concretamente para plantaciones de viñas entre ruinas de una ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4303', 'spa', 'Manjar sabroso, plato exquisito, delicia; especialmente el guiso de caza que Isaac pidió a Esaú.', 'Derivado de la raíz טָעַם (''gustar, saborear''), este sustantivo masculino designa manjares o alimentos sabrosos preparados con esmero. Seis de sus ocho apariciones se concentran en Génesis 27, donde Isaac pide a Esaú que le prepare manjares con caza antes de otorgar la bendición patriarcal (Gn 27:4, 7, 9, 14, 17, 31). Las dos restantes se hallan en Proverbios 23:3, 6, donde se advierte contra la codicia de las delicias engañosas de un gobernante. El español manjares capta bien el sentido de comida cuidadosamente preparada para deleitar el paladar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4305', 'spa', 'Enviar lluvia o hacer llover; hacer llover juicio destructivo desde el cielo; ser llovido. El verbo hebreo מָטַר en la raíz Hifil capta el dominio sob', 'Enviar lluvia o hacer llover; hacer llover juicio destructivo desde el cielo; ser llovido. El verbo hebreo מָטַר en la raíz Hifil capta el dominio soberano de Dios sobre la precipitación, tanto como bendición como ira. En su uso más común, describe al SEÑOR enviando lluvia sobre la tierra, como cuando Génesis registra que ''el SEÑOR Dios aún no había hecho llover'' (Gn 2:5) y Amós tres veces invoca a Dios reteniendo o enviando lluvia (Am 4:7). Sin embargo, el mismo verbo adquiere fuerza aterradora cuando Dios hace llover fuego y azufre sobre Sodoma (Gn 19:24) o trampas y carbones encendidos sobre los malvados (Sal 11:6). El raro Nifal pasivo en Amós 4:7 completa el panorama: un campo ''recibía lluvia'' mientras otro quedaba seco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4306', 'spa', 'Lluvia; precipitación enviada o retenida por Dios, considerada como bendición sobre la tierra o instrumento de juicio', 'Lluvia; precipitación enviada o retenida por Dios, considerada como bendición sobre la tierra o instrumento de juicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4307', 'spa', 'Guardia, casa de guardia, patio de la guardia (área de detención); también blanco o diana para disparar. Sustantivo femenino de la raíz que significa ', 'Guardia, casa de guardia, patio de la guardia (área de detención); también blanco o diana para disparar. Sustantivo femenino de la raíz que significa ''vigilar, guardar'' (נָטַר), que produce dos sentidos sorprendentemente divergentes. En Jeremías, aparece casi formulaicamente como ''el patio de la guardia'' (חֲצַר הַמַּטָּרָה), el recinto de detención dentro del palacio real donde el profeta fue confinado repetidamente (Jer 32:2; 37:21; 38:6). Nehemías menciona tanto el patio como una puerta con este nombre (Neh 3:25; 12:39). El segundo sentido, ''blanco'' o ''diana,'' se basa en la misma idea raíz de vigilar o fijar la mirada en algo. Job lamenta que Dios lo ha puesto ''como su blanco'' (Job 16:12), y Lamentaciones 3:12 usa el vívido símil ''como blanco para la flecha.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4310', 'spa', 'Pronombre interrogativo ''¿quién?'' para preguntar por la identidad de personas; también indefinido ''quienquiera que'' en contextos condicionales', 'Un pronombre interrogativo fundamental empleado para preguntar por la identidad de una persona: ''¿quién?'' o ''¿a quién?'' Aparece a lo largo de toda la Biblia hebrea en preguntas directas como ''¿Quién te lo dijo?'' (Gn 3:11) y ''¿Quién es este hombre?'' (Gn 24:65). Las traducciones interlingüísticas lo rinden consistentemente con pronombres interrogativos dedicados (español quién, francés qui, alemán wer), confirmando su función primaria. En un conjunto menor de pasajes adquiere un valor indefinido o generalizador —''quienquiera que'', ''todo el que''—, como en la convocatoria de Moisés: ''El que esté del lado del SEÑOR, venga a mí'' (Éx 32:33) y el desafío de Gedeón (Jue 7:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4311', 'spa', 'Medeba: ciudad moabita en la meseta al este del Jordan', 'Medeba era una antigua ciudad situada en la altiplanicie de Moab, al este del mar Muerto. Aparece en la narrativa de la conquista como territorio arrebatado a Sehon (Nm 21:30) y fue asignada a la tribu de Ruben (Jos 13:9, 16). En 1 Cronicas 19:7, los amonitas se reunieron alli antes de la batalla contra David. Isaias 15:2 la incluye en el oraculo contra Moab. La Inscripcion de Mesa tambien menciona la ciudad, confirmando su importancia en la geopolitica transjordana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4315', 'spa', 'Lo mejor de, la porción más selecta; sustantivo constructo superlativo para la calidad más fina de un campo, rebaño o tierra.', 'Sustantivo masculino usado exclusivamente en estado constructo para expresar un superlativo: «lo mejor de» algo. Aparece en dos contextos narrativos. En la historia de José, Faraón concede a la familia de Jacob «lo mejor de la tierra» de Egipto (Gén 47:6, 11). En la ley de restitución, quien permita que su ganado paste en campo ajeno debe pagar con «lo mejor de su propio campo y lo mejor de su viña» (Éx 22:4). Samuel reprende a Saúl por perdonar «lo mejor de las ovejas y del ganado» (1 Sam 15:9, 15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4316', 'spa', 'Mica, nombre de varios individuos del período postexílico', 'Nombre personal que aparece en contextos genealógicos y administrativos, destacándose como hijo de Mefiboset y nieto de Jonatán (2 Samuel 9:12), lo cual aseguró la continuación del linaje de Saúl. El nombre también aparece entre los levitas de la comunidad postexílica (1 Crónicas 9:15, Nehemías 11:22) y entre quienes sellaron el pacto de Nehemías (Nehemías 10:11). Probablemente sea una forma abreviada de Micaías («¿Quién es como el Señor?»), reflejo de la piedad teofórica en la práctica de dar nombres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4317', 'spa', 'Miguel — ''¿Quién como Dios?''; nombre propio de varios hombres y del ángel patrono de Israel', 'Miguel — ''¿Quién como Dios?''; nombre propio de varios hombres y del ángel patrono de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4318', 'spa', 'Miqueas; nombre propio llevado por varios personajes bíblicos, especialmente el efrateo de Jueces y el profeta', 'Miqueas; nombre propio llevado por varios personajes bíblicos, especialmente el efrateo de Jueces y el profeta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4320', 'spa', 'Micaias: forma extendida del nombre Miqueas, portado por varios israelitas', 'Micaias es una forma ampliada del nombre Miqueas, cuyo significado es ''?Quien es como Yahve?''. Designa a varios individuos distintos en la Biblia hebrea. Jeremias 26:18 emplea esta grafia del Ketiv para referirse al profeta canonico Miqueas de Moreset (el Qere lee Miqueas, como en Mi 1:1). Tambien nombra a un musico levita en Nehemias 12:35, a un sacerdote que participo en la dedicacion del muro de Jerusalen (Neh 12:41) y al padre de Acbor en 2 Reyes 22:12, cuyo paralelo en 2 Cronicas 34:20 abrevia el nombre a Miqueas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4321', 'spa', 'Micaías — nombre propio teofórico que significa ''¿quién es como YHWH?''. El portador más destacado es el profeta Micaías hijo de Imlá, quien se opuso v', 'Micaías — nombre propio teofórico que significa ''¿quién es como YHWH?''. El portador más destacado es el profeta Micaías hijo de Imlá, quien se opuso valientemente a los cuatrocientos profetas de la corte de Acab al profetizar desastre contra su campaña a Ramot de Galaad (1 R 22:8–28; 2 Cr 18:7–27). Esta escena dramática constituye uno de los retratos más vívidos de integridad profética bajo presión política en toda la Biblia. El nombre también pertenece a un efraimita (Jue 17:1, 4) y a un contemporáneo de Jeremías (Jer 36:11, 13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4324', 'spa', 'Mical: la hija menor del rey Saúl y primera esposa de David. Amó a David y lo ayudó a escapar de los asesinos de Saúl descolgándolo por una ventana y ', 'Mical: la hija menor del rey Saúl y primera esposa de David. Amó a David y lo ayudó a escapar de los asesinos de Saúl descolgándolo por una ventana y colocando un ídolo doméstico en su cama (1 S 19:11-17). Tras ser entregada por Saúl a Palti hijo de Lais (1 S 25:44), David exigió su devolución como condición de alianza con Abner (2 S 3:13-14). Su nombre es probablemente una forma contracta de Miguel, que significa ''¿quién es como Dios?''. Su historia termina en distanciamiento cuando despreció a David por danzar ante el arca (2 S 6:16-23). La Septuaginta traduce su nombre como Melcol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4325', 'spa', 'Agua en todas sus formas: bebida, ríos, mares, lluvia, diluvios y purificación ritual; el líquido elemental de vida y juicio', 'Uno de los sustantivos más frecuentes de la Biblia hebrea, מַיִם aparece cerca de 600 veces y siempre en forma plural, reflejando la percepción antigua del agua como una realidad envolvente y dinámica más que como una sustancia singular. Abarca toda la gama de referencias acuáticas: las aguas primordiales de la creación (Gn 1:6), las aguas catastróficas del diluvio (Gn 6:17), los pozos y manantiales que dan vida (Gn 21:19), la purificación ritual (Lv 14:8) y las aguas metafóricas de la angustia y la salvación (Sal 69:1). Cada tradición traductora principal lo rinde con su término básico para agua —inglés water, español agua, francés eau, alemán Wasser—, confirmando la transparencia universal de esta acepción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4326', 'spa', 'Mijamín, nombre de varios sacerdotes', 'Nombre sacerdotal que aparece con diversas grafías en Crónicas, Esdras y Nehemías. Designa una división sacerdotal establecida durante la organización del servicio del templo por David (1 Crónicas 24:9), sacerdotes que regresaron con Zorobabel (Nehemías 12:5), quienes sellaron el pacto de Nehemías (Nehemías 10:7), y uno que había tomado por esposa a una mujer extranjera durante el exilio (Esdras 10:25). La variación ortográfica refleja la fluidez en la escritura de nombres hebreos en el período postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4327', 'spa', 'Especie, género; categoría de ser vivo, siempre en la fórmula ''según su especie'' en textos de creación y legislación', 'Especie, género; categoría de ser vivo, siempre en la fórmula ''según su especie'' en textos de creación y legislación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4330', 'spa', 'Estrujamiento, presión; el acto de exprimir o apretar', 'Sustantivo que denota la acción de estrujar o apretar algo para extraer su contenido. Aparece únicamente en Proverbios 30:33 dentro de un dicho comparativo triple: estrujar la leche produce cuajada, estrujar la nariz produce sangre, y estrujar la ira produce contienda. El término capta la acción física de aplicar presión para forzar la salida de algo. El versículo emplea estos ejemplos concretos para advertir que provocar o presionar la ira conduce inevitablemente al conflicto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4332', 'spa', 'Misael, nombre propio que significa ''¿quién es lo que Dios es?'', llevado por un levita, un compañero de Daniel y un líder postexílico', 'Nombre propio masculino hebreo cuya construcción teofórica pregunta «¿Quién es lo que Dios es?». Identifica a tres individuos distintos de diferentes épocas: un levita primo de Moisés y Aarón que ayudó a retirar los cuerpos de Nadab y Abiú (Éx 6:22; Lv 10:4), uno de los tres compañeros judíos de Daniel en Babilonia, luego renombrado Mesac (Dn 1:6-7, 11, 19; 2:17), y un hombre que estuvo junto a Esdras durante la lectura pública de la Torá (Neh 8:4). El cambio de nombre babilónico del compañero de Daniel subraya la tensión entre la identidad teofórica hebrea y la asimilación imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4334', 'spa', 'Llanura, meseta; terreno llano y parejo; rectitud o equidad en el juicio', 'Llanura, meseta; terreno llano y parejo; rectitud o equidad en el juicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4336', 'spa', 'Mesac; nombre babilónico asignado a Misael, uno de los tres compañeros de Daniel en la corte de Nabucodonosor', 'Mesac; nombre babilónico asignado a Misael, uno de los tres compañeros de Daniel en la corte de Nabucodonosor');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4339', 'spa', 'Rectitud, equidad, integridad en el juicio y la conducta; suavidad o uniformidad (sentido literal); acuerdo o términos equitativos. El sustantivo plur', 'Rectitud, equidad, integridad en el juicio y la conducta; suavidad o uniformidad (sentido literal); acuerdo o términos equitativos. El sustantivo plural מֵישָׁרִים deriva de la raíz y-sh-r (''ser recto'') y encarna el ideal hebreo de rectitud moral aplicado a la gobernanza, el habla y la vida cotidiana. Aparece casi exclusivamente en poesía —Salmos, Proverbios e Isaías— donde describe cómo Dios juzga ''con equidad'' (Sal 9:8; 96:10; 98:9) y cómo los sabios hablan ''rectamente'' (Is 33:15; Pr 23:16). Una encantadora supervivencia literal aparece en Cantares 7:9 y Proverbios 23:31, donde se dice que el vino baja ''suavemente'', la misma palabra ahora describiendo el fluir del líquido en vez de las balanzas de la justicia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4340', 'spa', 'Cuerda o soga, especialmente cuerda de tienda para asegurar el tabernáculo o campamento; también cuerda de arco.', 'Relacionado con la raíz יָתַר (''quedar, extender''), este sustantivo designa una cuerda tensada, generalmente las sogas que anclan una tienda. Seis de sus nueve apariciones describen las cuerdas del tabernáculo y su atrio (Éx 35:18; 39:40; Nm 3:26, 37; 4:26, 32), convirtiéndolo en término técnico de la legislación sacerdotal. Jeremías 10:20 lamenta que «mis cuerdas se han roto», usando la soga de tienda desgarrada como imagen del colapso nacional. Isaías 54:2 invierte la figura: extiende tus cuerdas, porque Dios amplía tu morada. Una sola ocurrencia en el Salmo 21:13 cambia de cuerdas de tienda a cuerdas de arco, donde Dios apunta sus cuerdas contra el rostro de sus enemigos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4341', 'spa', 'Dolor, pesar, sufrimiento — aflicción física o angustia emocional, con un arco teológico que va desde la esclavitud de Israel en Egipto hasta el Sierv', 'Dolor, pesar, sufrimiento — aflicción física o angustia emocional, con un arco teológico que va desde la esclavitud de Israel en Egipto hasta el Siervo Sufriente de Isaías. Dios emplea esta palabra por primera vez cuando dice a Moisés ''he visto el dolor de mi pueblo'' en Egipto (Éx 3:7), estableciéndola como término de aflicción comunitaria. Los Salmos la aplican al sufrimiento personal causado por el pecado (Sal 32:10; 38:18; 69:27). Eclesiastés hace la provocadora afirmación de que el aumento del conocimiento aumenta el מַכְאוֹב (Ec 1:18). De modo memorable, Isaías 53:3-4 describe al Siervo como ''varón de dolores'' (אִישׁ מַכְאֹבוֹת) que ''cargó nuestros dolores'', lenguaje que el Nuevo Testamento aplica a Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4345', 'spa', 'Enrejado o celosía de bronce; componente del altar del holocausto del tabernáculo (solo en Éxodo).', 'Sustantivo masculino que designa el enrejado o celosía de bronce que formaba parte del altar del holocausto en el tabernáculo. Las seis ocurrencias se limitan a Éxodo, apareciendo en las instrucciones iniciales (Éx 27:4), el inventario de componentes (Éx 35:16; 38:30; 39:39) y la narrativa de construcción (Éx 38:4-5). El enrejado fue fabricado como «obra de rejilla de bronce» (מַעֲשֵׂה רֶשֶׁת נְחֹשֶׁת), colocado debajo del reborde del altar. El español «enrejado» capta el sentido con precisión, señalando una estructura de metal calado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4347', 'spa', 'Golpe, herida; plaga o calamidad divina; matanza en batalla.', 'Golpe, herida; plaga o calamidad divina; matanza en batalla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4348', 'spa', 'Quemadura: marca, cicatriz o mancha en la piel causada por el fuego', 'Mikwa se refiere especificamente a una cicatriz o mancha de quemadura en la piel, y aparece exclusivamente en la legislacion sacerdotal sobre enfermedades cutaneas de Levitico 13:24-28. El sacerdote debe examinar si una quemadura producida por fuego ha desarrollado signos de una condicion leprosa. Las cinco apariciones del termino se refieren al mismo escenario diagnostico: distinguir una simple cicatriz de quemadura de una enfermedad cutanea en expansion. El vocablo hebreo se construye siempre con אֵשׁ (''fuego''), formando la expresion מִכְוַת־אֵשׁ (''quemadura de fuego'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4349', 'spa', 'Lugar establecido o fundamento; morada fija, especialmente la sede celestial de Dios o su santuario terrenal. Derivado de la raíz כּוּן (''establecer, ', 'Lugar establecido o fundamento; morada fija, especialmente la sede celestial de Dios o su santuario terrenal. Derivado de la raíz כּוּן (''establecer, hacer firme''), este sustantivo designa un lugar que ha sido deliberadamente fijado y asegurado — no un sitio temporal sino un fundamento permanente. Su uso principal es teológico: el ''lugar establecido'' de la morada de Dios, ya sea su sala del trono celestial desde donde escucha la oración (1 R 8:39, 43, 49) o el santuario terrenal que él ha preparado (Éx 15:17). Un uso secundario describe los fundamentos cósmicos o morales que sostienen el gobierno de Dios, como en ''justicia y derecho son el fundamento de su trono'' (Sal 89:14; 97:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4350', 'spa', 'Base fija, soporte con ruedas o pedestal; especialmente las basas de bronce para las pilas del templo de Salomón', 'Base fija, soporte con ruedas o pedestal; especialmente las basas de bronce para las pilas del templo de Salomón');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4351', 'spa', 'Origen, procedencia; lugar de extracción o nacimiento', 'Sustantivo que denota origen o procedencia, literalmente el lugar de donde algo fue extraído o sacado. Ezequiel lo emplea tres veces en oráculos de juicio. De Jerusalén dice que ''tu origen y tu nacimiento'' son de la tierra de Canaán (16:3). Contra Faraón, menciona juzgarlo ''en la tierra de tu origen, donde fuiste creado'' (21:30). Y de Egipto profetiza que será devuelto ''a la tierra de su origen'' (29:14). El término enfatiza las raíces, la patria y el lugar ancestral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4353', 'spa', 'Makir (''vendedor''); hijo mayor de Manasés y antepasado de los maquiritas, también un benefactor de David.', 'Makir (''vendedor''); hijo mayor de Manasés y antepasado de los maquiritas, también un benefactor de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4355', 'spa', 'Hundirse, ser humillado, ser abatido o rebajado', 'Verbo que significa hundirse, descender o ser humillado. Aparece en las formas Qal, Nifal y Hofal para describir declive y degradación. El Salmo 106:43 recuerda cómo Israel rebelde fue abatido repetidamente por su iniquidad. Eclesiastés lo emplea para describir una casa cuyas vigas se hunden por la negligencia (10:18). Job habla de los impíos que finalmente son humillados (24:24). El verbo capta el movimiento descendente del deterioro, la derrota o la humillación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4356', 'spa', 'Redil, aprisco, corral para ovejas o cabras', 'Sustantivo que designa un recinto o redil donde se recogen las ovejas para protegerlas durante la noche. El salmista emplea dos veces la imagen de Dios tomando a alguien de los rediles: a David, que pastoreaba el rebaño (78:70), y a los machos cabríos de los corrales del adorador (50:9). Habacuc lamenta el juicio devastador cuando las ovejas son cortadas del redil (3:17). El término evoca la vida pastoril y los recintos protectores que resguardaban los rebaños de los depredadores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4363', 'spa', 'Micmas — ciudad benjaminita en un paso estratégico al noreste de Jerusalén, prominente en las guerras de Saúl contra los filisteos', 'El nombre propio מִכְמָס (Micmas) designa una ciudad en el territorio de Benjamín, ubicada en un paso rocoso al noreste de Jerusalén, frente a Geba. Saúl estaciona tropas allí (1 Sam 13:2), los filisteos acampan en el desfiladero (1 Sam 13:5, 16, 23) y Jonatán aprovecha el estrecho paso entre dos peñascos para su audaz ataque (1 Sam 14:5, 31). Isaías describe un avance asirio que pasa por Micmas (Isa 10:28). Tras el exilio, se cuentan hombres de Micmas entre los colonos que regresaron (Esd 2:27; Neh 7:31; 11:31). El sitio se identifica con la moderna Mukhmas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4370', 'spa', 'Calzoncillos de lino: ropa interior sacerdotal prescrita para el servicio en el santuario', 'מִכְנָס designa la ropa interior de lino prescrita para el sacerdocio israelita, y aparece siempre en forma constructa dual o plural (מִכְנְסֵי). Estos calzoncillos se confeccionaban de lino fino (בַּד o פִּשְׁתִּים) y se vestian para cubrir el cuerpo desde la cintura hasta el muslo durante el servicio sagrado. Figuran en las instrucciones de investidura (Ex 28:42; 39:28), en las normas para el holocausto diario (Lv 6:10), en los ritos del Dia de la Expiacion (Lv 16:4) y en la vision escatologica del templo de Ezequiel (Ez 44:18). La prenda aseguraba el recato sacerdotal ante el altar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4371', 'spa', 'Tributo, impuesto, gravamen: contribución proporcional sobre el botín de guerra dedicada al SEÑOR y a los levitas (solo Números 31).', 'Sustantivo masculino que significa ''tributo'' o ''impuesto'', utilizado exclusivamente en Números 31:28-41, donde designa la contribución proporcional exigida del botín de la guerra contra Madián. Dios ordena a Moisés separar un tributo de la porción de los guerreros (uno de cada quinientos: personas, ganado, asnos y ovejas) y de la porción de la congregación (uno de cada cincuenta). El término tiene cognados en arameo (מִכְסָא), siríaco e incluso árabe (مَكْسٌ, préstamo lingüístico), todos con el significado de ''impuesto'' o ''derecho aduanero''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4372', 'spa', 'Cubierta — las capas protectoras exteriores de piel colocadas sobre el tabernáculo y sus enseres sagrados', 'Cubierta — las capas protectoras exteriores de piel colocadas sobre el tabernáculo y sus enseres sagrados');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4374', 'spa', 'cubierta, cobertura (de grasa, vestiduras, cubierta de barco, gusanos)', 'Término que designa algo que cubre u oculta, aplicado a contextos muy diversos. Describe la grasa que recubre los órganos internos en los rituales de sacrificio (Levítico 9:19), la cubierta de un barco fenicio (Ezequiel 27:7), vestiduras lo suficientemente valiosas como para ser almacenadas por los mercaderes (Isaías 23:18), e incluso los gusanos que cubren a los muertos en el Seol (Isaías 14:11). El hilo semántico que conecta estos usos es la función de cubrir o recubrir algo que se encuentra debajo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4375', 'spa', 'Macpela: el lugar de sepultura cerca de Hebrón donde fueron enterrados los patriarcas Abraham, Isaac, Jacob y sus esposas.', 'Nombre propio que aparece siempre con artículo (הַמַּכְפֵּלָה), designando el campo y la cueva cerca de Hebrón que Abraham compró a Efrón el hitita como sepultura familiar (Gn 23). El nombre pudo haber sido originalmente un apelativo que significaba ''la cueva doble''; la Septuaginta lo traduce como τὸ διπλοῦν, aunque esta etimología sigue siendo debatida. Allí fueron sepultados Abraham y Sara, Isaac y Rebeca, y Jacob y Lea (Gn 23:19; 25:9; 49:30; 50:13). Aparece exclusivamente en la fuente Sacerdotal y siempre en contextos funerarios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4376', 'spa', 'Vender (bienes, propiedades o personas); en Nifal, ser vendido; en Hitpael, venderse a la servidumbre o al mal.', 'Vender (bienes, propiedades o personas); en Nifal, ser vendido; en Hitpael, venderse a la servidumbre o al mal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4377', 'spa', 'Mercancía, precio, valor de bienes', 'Sustantivo que designa mercancía para la venta, o el precio y valor de los bienes. Nehemías lo usa para las mercancías traídas por comerciantes en día de reposo (13:16). Números lo aplica al precio del agua que Israel solicitó a Edom (20:19). Proverbios lo emplea para el valor de la mujer virtuosa: ''su precio supera con creces al de las piedras preciosas'' (31:10). El término abarca los bienes comerciales, su precio y, por extensión, el valor o mérito de cualquier cosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4383', 'spa', 'Tropiezo, obstáculo; causa de caída, ya sea obstrucción física o ruina moral y espiritual', 'Tropiezo, obstáculo; causa de caída, ya sea obstrucción física o ruina moral y espiritual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4385', 'spa', 'Escritura, inscripción; el acto o producto de escribir, desde el grabado divino en tablas de piedra hasta cartas proféticas y edictos reales.', 'Designa el acto de escribir o su producto tangible, ya sea grabado por el dedo mismo de Dios o trazado por mano humana. En Éxodo 32:16 el término alcanza su uso más sublime: «la escritura era escritura de Dios, grabada sobre las tablas». La palabra también abarca documentos oficiales: una carta profética de Elías (2 Cr 21:12) y decretos reales (2 Cr 36:22). Isaías 38:9 la emplea en el encabezado del salmo de acción de gracias de Ezequías tras su recuperación de la enfermedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4387', 'spa', 'Mictam: término técnico de significado incierto en los títulos de salmos, hallado solo en encabezados atribuidos a David.', 'Término musical o litúrgico que aparece en los títulos de seis salmos (Sal 16, 56-60), siempre vinculado a David. Su significado preciso ha eludido a los eruditos durante siglos. La Septuaginta lo tradujo como stelographia (''inscripción en columna''), sugiriendo un escrito grabado o permanente. Algunos lo relacionan con la raíz hebrea k-t-m (''oro'') y proponen ''salmo áureo'', mientras otros lo conectan con un cognado acadio que significa ''cubrir'', interpretándolo como oración expiatoria. Independientemente de su sentido original, estos seis salmos comparten temas de confianza urgente en Dios ante el peligro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4390', 'spa', 'Estar lleno, llenar; cumplir, completar; saciar; seguir plenamente; engastar piedras preciosas', 'Una raíz que expresa plenitud en los dominios físico, temporal y metafórico. En su forma Qal estativa significa ''estar lleno'': la tierra está llena de violencia, la casa llena de gloria. El Piel llena activamente algo: Dios ordena a la humanidad llenar la tierra, el siervo de Eliseo llena tinajas con agua. Pero la raíz se extiende a la completación abstracta: cumplir promesas, completar períodos de tiempo (la semana nupcial de Raquel, los setenta años de cautiverio). Existe un modismo especializado para seguir a Dios plenamente (literalmente ''llenar detrás de''). Una acepción técnica aparece en contextos de joyería: engastar piedras preciosas. Las 250 apariciones revelan cómo los hablantes de hebreo concebían plenitud y completación como conceptos unificados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4392', 'spa', 'Lleno, colmado, completo — ya sea de contenido físico, plenitud de medida, embarazo o intensidad vocal.', 'Lleno, colmado, completo — ya sea de contenido físico, plenitud de medida, embarazo o intensidad vocal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4393', 'spa', 'Plenitud, la medida completa o el contenido total de algo; por extensión, un grupo completo de personas', 'Plenitud, la medida completa o el contenido total de algo; por extensión, un grupo completo de personas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4394', 'spa', 'Ordenación o consagración sacerdotal (''llenado de las manos''); también el engaste o montura para piedras preciosas.', 'Ordenación o consagración sacerdotal (''llenado de las manos''); también el engaste o montura para piedras preciosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4395', 'spa', 'Plenitud, producción completa; el rendimiento íntegro del campo, la viña o el lagar, o el estado de estar lleno.', 'Este sustantivo femenino expresa plenitud o producción completa: la cosecha íntegra del campo, la viña o el lagar. En Éxodo 22:29, «tu plenitud» se refiere a las primicias del producto agrícola debido a Dios. Números 18:27 compara el diezmo de los levitas con «la plenitud del lagar», mientras que Deuteronomio 22:9 advierte que la siembra mixta hará perder «la plenitud de la semilla». El término también puede describir una ciudad llena de algo, como en Isaías 1:21, donde Jerusalén estuvo una vez «llena de justicia».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4396', 'spa', 'Engaste, montura para piedras preciosas en las vestiduras sacerdotales', 'Sustantivo que designa el engaste o montura de piedras preciosas, específicamente en el pectoral del sumo sacerdote. Las tres apariciones se encuentran en Éxodo, en las instrucciones detalladas para las vestiduras sacerdotales. El pectoral debía llevar cuatro hileras de piedras preciosas ''en engastes de oro'' o ''montadas en sus monturas'' (28:17, 20; 39:13). El término subraya la cuidadosa artesanía requerida para fijar cada piedra valiosa en su engaste de oro, formando el pectoral sagrado que representaba a las doce tribus de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4397', 'spa', 'Mensajero o ángel; un enviado humano en misión, o un ser celestial divino enviado por Dios', 'Mal''āḵ significa sencillamente ''el que es enviado'', ya sea un correo humano (Gn 32:3) o un ser celestial (Gn 16:7). La genialidad de esta palabra reside en su ambigüedad: el ''ángel del SEÑOR'' que se aparece a Agar, Moisés y Gedeón puede resultar indistinguible de Dios mismo. El árabe distingue limpiamente entre rasūl (mensajero humano) y malak (ángel), mientras que el coreano emplea 사자 para enviados y 천사 para ángeles. El español ''ángel'' proviene del griego ἄγγελος, que a su vez traduce esta misma palabra hebrea: un recordatorio de que el concepto de ''ángel'' no nace con alas y aureolas, sino con el acto de ser enviado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4399', 'spa', 'Obra, trabajo, labor; artesanía; propiedad, bienes; toda actividad productiva, desde la construcción del templo hasta el quehacer diario', 'Melā''ḵāh es el término más amplio de la Biblia hebrea para la actividad productiva y sus resultados. Abarca desde los seis días de la obra creadora de Dios (Gn 2:2) hasta la artesanía de Bezalel en la construcción del tabernáculo (Éx 31:3-5), desde la prohibición sabática de ''toda obra'' (Éx 20:10) hasta la reconstrucción de los muros de Jerusalén por Nehemías. El árabe ''amal y el alemán Werk se centran en la producción con esfuerzo, mientras que el francés distingue entre travail (labor), ouvrage (producto) y oeuvre (obra artística). Dos acepciones marginales —propiedad y empresa comercial— muestran la extensión metonímica de la actividad a lo que ella produce.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4403', 'spa', 'Vestimenta, ropa, indumentaria; vestidura exterior como señal de estatus, riqueza o identidad.', 'Este sustantivo masculino designa la vestimenta o indumentaria, frecuentemente con connotaciones de estatus o identidad. Describe las vestiduras entregadas a los adoradores de Baal (2 R 10:22), las impresionantes ropas de los siervos de Salomón que dejaron sin aliento a la reina de Sabá (1 R 10:5; 2 Cr 9:4) y la vestimenta extranjera condenada por el profeta Sofonías (Sof 1:8). Isaías lo emplea dramáticamente para retratar a Dios como guerrero cuyas vestiduras están teñidas de haber pisado el lagar del juicio (Is 63:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4404', 'spa', 'molde o horno de ladrillos; terraza de ladrillos', 'Término relacionado con la fabricación de ladrillos, con dos posibles significados: el molde usado para dar forma a los ladrillos o el horno para cocerlos. David sometió a los amonitas conquistados a trabajos forzados «junto al molde/horno de ladrillos» (2 Samuel 12:31), indicando condiciones de labor severa. Jeremías lo emplea para referirse a una terraza o pavimento de ladrillos en Tafnes donde Nabucodonosor establecería su trono (Jeremías 43:9). Nahúm ordena a Nínive, en tono de burla, que «pise el barro y refuerce el molde de ladrillos», preparando defensas inútiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4405', 'spa', 'Palabra, expresión, discurso; sinónimo poético de ''dabar'', concentrado casi exclusivamente en Job', 'Palabra, expresión, discurso; sinónimo poético de ''dabar'', concentrado casi exclusivamente en Job');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4406', 'spa', 'Sustantivo arameo: palabra, declaración, decreto real; también asunto, cosa, cuestión.', 'Sustantivo arameo: palabra, declaración, decreto real; también asunto, cosa, cuestión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4407', 'spa', 'Millo — terraplén o terraza de relleno fortificada, estructura clave en Jerusalén y cerca de Siquem', 'Derivado de la raíz m-l-ʾ (''llenar''), Millo designa un gran terraplén de relleno o terraza de piedra que servía como fortificación. Dos estructuras distintas llevan este nombre: una cerca de Siquem, llamada bêth millôʾ (''casa de Millo'', Jue 9:6, 20), vinculada a la aristocracia siquemita en el relato de Abimelec; y el más célebre Millo de Jerusalén, una obra de ingeniería que David construyó tras conquistar la ciudad (2 Sam 5:9) y que Salomón reforzó después (1 Re 9:15, 24; 11:27). El cognado acadio mulû (''terraplén, montículo'') confirma el significado arquitectónico. El rey Joás fue asesinado en bêth millōʾ (2 Re 12:21), lo que demuestra su importancia continuada siglos más tarde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4409a', 'spa', 'Maluc: nombre propio de varios levitas y laicos en el Israel postexílico.', 'Nombre propio hebreo que quizá significa ''consejero'' o ''rey'' (de la raíz m-l-k), llevado por al menos seis individuos distintos en el período postexílico. Maluc aparece entre los levitas en la genealogía del Cronista (1 Cr 6:44), entre quienes habían tomado esposas extranjeras durante la reforma de Esdras (Esd 10:29, 32), y entre los que sellaron el pacto bajo Nehemías (Neh 10:4, 27). La Septuaginta lo traduce de diversas formas como Maloch y Malouch, reflejando variación dialectal en la transliteración griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4410', 'spa', 'Realeza, autoridad real, soberanía: el oficio y la dignidad de reinar como rey.', 'Realeza, autoridad real, soberanía: el oficio y la dignidad de reinar como rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4411', 'spa', 'Posada, mesón o lugar de alojamiento nocturno; refugio temporal para viajeros o campamento para pernoctar', 'Este sustantivo designa una posada o mesón, cualquier lugar donde los viajeros se detienen a pasar la noche. Aparece memorablemente en la narrativa de José, cuando sus hermanos descubren la plata devuelta en el mesón (Gn 42:27; 43:21), y en el misterioso encuentro nocturno en la posada durante el viaje de Moisés de regreso a Egipto (Éx 4:24). Josué lo usa para el campamento nocturno de Israel al cruzar el Jordán (Jos 4:3, 8). Jeremías anhela un «albergue de caminantes» en el desierto (Jer 9:2). El término evoca la rústica sencillez de aquellos antiguos refugios junto al camino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4414b', 'spa', 'salar, sazonar con sal', 'Verbo denominativo que significa sazonar o tratar con sal, presente en contextos cultuales y metafóricos. Todas las ofrendas de cereal debían ser saladas (Levítico 2:13), estableciendo un «pacto de sal» que simbolizaba permanencia y preservación. La mezcla de incienso era «salada» o sazonada (Éxodo 30:35). La metáfora de Ezequiel sobre Jerusalén como una recién nacida abandonada incluye el detalle de que no fue salada (Ezequiel 16:4), una práctica de frotar sal sobre los neonatos, quizá por higiene o purificación simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4416', 'spa', 'Sal (arameo)', 'Sustantivo arameo que significa sal, presente solo en Esdras en contextos de provisiones reales persas. La sal se menciona dos veces como provisión suministrada para los sacrificios (6:9; 7:22) y una vez en sentido figurado respecto a la obligación con el palacio: ''porque comemos la sal del palacio'' (4:14), expresión idiomática que indica estar al servicio real y, por tanto, obligado a proteger los intereses del rey. Las connotaciones de preservación y sellado de pactos que la sal tenía en la cultura antigua sustentan ambos usos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4417', 'spa', 'Sal; la sustancia mineral usada para sazonar, conservar y como símbolo de pacto, además frecuente en nombres geográficos (Mar Muerto, Valle de la Sal)', 'Sal; la sustancia mineral usada para sazonar, conservar y como símbolo de pacto, además frecuente en nombres geográficos (Mar Muerto, Valle de la Sal).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4419', 'spa', 'marineros, navegantes', 'Hombres de mar que operan embarcaciones, un préstamo lingüístico asirio que refleja el vocabulario marítimo internacional. El término aparece en la historia de Jonás durante la tempestad (Jonás 1:5) y extensamente en el lamento de Ezequiel sobre Tiro (Ezequiel 27:9, 27, 29), donde los marineros figuran junto a pilotos y calafateadores como profesionales marítimos esenciales. La caída de Tiro afecta no solo a la ciudad sino a toda la economía naviera que dependía de sus redes comerciales. El carácter de préstamo lingüístico sugiere la naturaleza técnica y especializada del oficio marítimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4420', 'spa', 'Salinidad, aridez salina; tierra baldía e improductiva por exceso de sal, símbolo de maldición y juicio divino', 'Sustantivo que designa la salinidad o la esterilidad provocada por la sal en la tierra. Job menciona la «tierra salada» como morada del asno salvaje (39:6). Jeremías advierte que quienes confían en el ser humano habitarán «tierra salada» donde nadie mora (17:6). El salmista celebra el poder soberano de Dios para convertir tierra fértil en salar como juicio, y salar en fuente de frutos como bendición (107:34). El suelo saturado de sal representa maldición, esterilidad y sentencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4421', 'spa', 'Guerra, batalla: conflicto armado entre fuerzas opuestas, ya sea un enfrentamiento puntual o una campaña prolongada', 'Milḥāmāh es el sustantivo principal de la Biblia hebrea para el conflicto armado, abarcando desde una sola batalla campal (Gn 14:8; 1 S 17:1) hasta una guerra prolongada (2 S 3:1, ''la guerra fue larga''). Derivado de la raíz ל-ח-מ (''combatir''), aparece en fórmulas como ''el Libro de las Guerras del SEÑOR'' (Nm 21:14) y ''varón de guerra'' (Éx 15:3). El español guerra, el francés guerre y el alemán Krieg captan todo su espectro sin necesidad de términos separados para batalla y guerra, reflejando la propia amplitud semántica de la palabra hebrea a lo largo de sus 319 apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4422', 'spa', 'Escapar, huir; en Piel, librar o rescatar; en uso raro, dar a luz o poner huevos.', 'Escapar, huir; en Piel, librar o rescatar; en uso raro, dar a luz o poner huevos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4427a', 'spa', 'Reinar, ser o llegar a ser rey; en Hifil, hacer rey a alguien o hacer que reine sobre un pueblo o territorio.', 'Verbo central de la teología política de Israel que designa el ejercicio de la autoridad real o la subida al trono. Cuando Samuel unge a Saúl y después a David, esta es la palabra que marca la transferencia del poder. En la conjugación Hifil adquiere fuerza causativa: el pueblo o Dios «hace rey a alguien», como cuando Israel corona a Saúl en Guilgal (1 Sam 11:15). El árabe malaka y el acadio malāku confirman la antigüedad de esta raíz como término estándar para la soberanía en todo el Próximo Oriente antiguo. La única aparición en Daniel 9:1 conserva un matiz pasivo poco frecuente: Darío «fue hecho rey», atestiguado también en las secciones arameas de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4428', 'spa', 'Rey: soberano humano que gobierna una ciudad, nación o territorio; también título divino de Dios como Rey supremo', 'מֶלֶךְ es el término principal de la Biblia hebrea para designar a un soberano gobernante, con más de 2500 apariciones que abarcan toda la historia de Israel —desde los reyes de Canaán en Génesis hasta los emperadores persas de Esdras-Nehemías. Todas las traducciones importantes lo vierten directamente: ''el rey'' en español, ''le roi'' en francés, ''der König'' en alemán. Sin embargo, un grupo reducido pero teológicamente significativo de apariciones aplica מֶלֶךְ directamente a Dios como Rey divino, especialmente en los Salmos: ''He establecido a mi Rey en Sion'' (Sal 2:6) y ''Escucha mi clamor, Rey mío y Dios mío'' (Sal 5:2) emplean la misma palabra para expresar el dominio soberano del SEÑOR sobre Israel y toda la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4429', 'spa', 'Mélec, nombre benjaminita; también «rey»', 'Nombre propio de un descendiente benjaminita de Micaía (1 Crónicas 8:35; 9:41), aunque la misma forma también significa «rey» en hebreo. Esto genera dificultades interpretativas en Jeremías 36:26 y 38:6, donde «hijo del rey» podría referirse a un príncipe real o a alguien llamado Mélec. La ambigüedad refleja la práctica común de emplear títulos como nombres personales y la dificultad de distinguir sustantivos comunes de nombres propios en textos antiguos sin puntuación vocálica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4430', 'spa', 'Rey — sustantivo arameo para un gobernante soberano, usado predominantemente de monarcas babilonios y persas en Daniel y Esdras.', 'Este sustantivo arameo equivale al hebreo mélek y aparece casi exclusivamente en Daniel y Esdras, las dos secciones arameas principales de la Biblia. La forma enfática malká («el rey») domina con más de 150 apariciones, reflejando la preferencia del arameo por el estado determinado. Nabucodonosor recibe el título de «rey de reyes» (mélek malkayá, Dn 2:37), título aplicado más tarde a Artajerjes (Esd 7:12). Todas las lenguas lo traducen con vocabulario real estándar — español rey, francés roi, alemán König — sin necesidad de adaptación especial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4432', 'spa', 'Moloc; deidad cananea asociada con el sacrificio de niños por fuego, condenada en la Torá y los Profetas.', 'Nombre de una aborrecible deidad pagana a la cual los israelitas tenían prohibido ofrecer a sus hijos por fuego. La vocalización reproduce deliberadamente las vocales de boshet (''vergüenza'') sobre las consonantes de melek (''rey''), expresando repudio al falso estatus divino-real de este ídolo. Levítico 18:21 y 20:2-5 prescriben la pena de muerte para quien ''dé su descendencia a Moloc'', mientras que Jeremías 32:35 vincula el culto a Moloc con el Valle de Hinom. En un caso debatido (Am 5:26), las mismas consonantes podrían significar simplemente ''vuestro rey'' en lugar del nombre de la deidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4435', 'spa', 'Milca — nombre propio de la esposa de Nacor (pariente de Abraham) y de una hija de Zelofehad', 'El nombre propio מִלְכָּה (Milca, ''reina'' o ''consejera'') identifica a dos mujeres en las Escrituras. La principal es Milca, hija de Harán y esposa de Nacor, hermano de Abraham (Gn 11:29). Ella constituye el vínculo matrilineal en la genealogía que conduce a Rebeca: el relato traza cuidadosamente a Milca como madre de Betuel y abuela de Rebeca y Labán (Gn 22:20, 23; 24:15, 24, 47). Su mención reiterada en las negociaciones nupciales subraya la continuidad del linaje dentro de la familia extendida de Abraham. La segunda Milca es hija de Zelofehad, de la tribu de Manasés, una de cinco hermanas cuya petición de derechos hereditarios establece un precedente legal fundamental (Nm 26:33; 27:1; 36:11; Jos 17:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4436', 'spa', 'Reina; mujer que reina o posee estatus de consorte real, especialmente la Reina de Sabá, Vasti y Ester', 'Reina; mujer que reina o posee estatus de consorte real, especialmente la Reina de Sabá, Vasti y Ester');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4437', 'spa', 'Reino, reinado o dominio real; término arameo para la soberanía, el territorio y la autoridad regia en Daniel y Esdras.', 'Reino, reinado o dominio real; término arameo para la soberanía, el territorio y la autoridad regia en Daniel y Esdras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4438', 'spa', 'Realeza, poder real, reinado o reino; el dominio, ejercicio o dignidad del gobierno regio (principalmente en hebreo tardío).', 'Realeza, poder real, reinado o reino; el dominio, ejercicio o dignidad del gobierno regio (principalmente en hebreo tardío).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4439', 'spa', 'Malquiel (nombre propio: ''Dios es mi rey'' o ''El es rey'')', 'Nombre propio que significa «Dios es mi rey» o «El es rey», perteneciente a un hijo de Bería de la tribu de Aser. Malquiel aparece en tres listas genealógicas paralelas: Génesis 46:17 (la familia de Jacob que desciende a Egipto), Números 26:45 (el censo en el desierto) y 1 Crónicas 7:31 (genealogías tribales). Sus descendientes formaron un clan dentro de Aser. El nombre teofórico refleja la fe en la soberanía divina, tema recurrente en la onomástica israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4441', 'spa', 'Malquías / Malquiyá — nombre teofórico compuesto de מֶלֶךְ (''rey'') y Yah (el nombre divino), que significa ''mi rey es el SEÑOR''. Lo llevan al menos di', 'Malquías / Malquiyá — nombre teofórico compuesto de מֶלֶךְ (''rey'') y Yah (el nombre divino), que significa ''mi rey es el SEÑOR''. Lo llevan al menos diez individuos distintos repartidos en Crónicas, Esdras, Nehemías y Jeremías. Entre los más notables están el sacerdote cuyo descendiente Pasjur servía en Jerusalén (1 Cr 9:12; Neh 11:12; Jer 21:1; 38:1), el turno sacerdotal al que correspondió la quinta suerte en la organización templaria de David (1 Cr 24:9) y el príncipe real dueño de la cisterna en la que fue arrojado Jeremías (Jer 38:6). Varios portadores aparecen en la comunidad postexílica: hombres que repudiaron esposas extranjeras (Esd 10:25, 31), constructores que repararon las murallas de Jerusalén (Neh 3:11, 14, 31) y un participante en la ceremonia de dedicación (Neh 12:42).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4444', 'spa', 'Malquisua: hijo del rey Saul, cuyo nombre significa ''mi rey es opulencia''', 'Malquisua fue uno de los hijos del rey Saul, mencionado junto a Jonatan, Isvi y otros. El nombre probablemente significa ''mi rey es opulencia'' o ''mi rey es salvacion'', con el elemento divino entendido como referencia a Yahve. Cayo junto a su padre y hermanos en el monte Gilboa en la catastrofica batalla contra los filisteos (1 S 31:2; 1 Cr 10:2). Las genealogias de Cronicas conservan su nombre en ambas listas benjaminitas (1 Cr 8:33; 9:39), a veces con guion como Malqui-sua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4445b', 'spa', 'Milcom, dios de los amonitas', 'Deidad nacional de Amón, introducida en Israel a través de las esposas extranjeras de Salomón (1 Reyes 11:5, 33). Llamado «la abominación de los amonitas», Milcom tuvo un lugar alto edificado en su honor en el Monte de los Olivos, que Josías profanó durante sus reformas (2 Reyes 23:13). El nombre aparece en textos proféticos que condenan el culto sincretista (Sofonías 1:5) y en oráculos contra Amón (Jeremías 49:1, 3). El nombre de esta deidad posiblemente se relaciona con la palabra «rey» (מֶלֶךְ), significando quizá «su rey» o representando un rey divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4446', 'spa', 'reina (del cielo) — título de una diosa, probablemente Istar o Astarté', 'Este sustantivo femenino aparece exclusivamente en la expresión «reina del cielo», designando a una diosa a la que las mujeres de Judá rendían culto con incienso, libaciones y tortas con su imagen. Jeremías condena enérgicamente este culto (Jer 7:18; 44:17-19, 25), mientras las mujeres insisten desafiantes en que la prosperidad acompañaba su devoción. La divinidad suele identificarse con la mesopotámica Istar (Venus) o la cananea Astarté. Algunos estudiosos leen la palabra como derivada de «obra, culto», pero la vocalización tradicional como «reina» goza de amplia aceptación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4448a', 'spa', 'hablar, pronunciar, declarar', 'Verbo en forma Piel que significa hablar o declarar, presente sobre todo en la literatura poética y sapiencial. Sara lo emplea al preguntarse quién le habría dicho a Abraham que ella amamantaría hijos (Génesis 21:7). Los interlocutores de Job lo usan al exponer sus argumentos (Job 8:2, 33:3), y el salmista pregunta quién puede pronunciar todas las proezas del Señor (Salmo 106:2). El término enfatiza el acto mismo de la expresión verbal, la articulación de pensamientos o conocimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4449', 'spa', 'hablar, decir (arameo Pael) — usado tanto del habla humana como de pronunciamientos arrogantes', 'Este verbo arameo en la conjugación Pael significa «hablar» o «decir», cognado con el raro Piel hebreo de la misma raíz. Sus cinco apariciones se concentran en Daniel. En Dan 6:21, Darío habla con Daniel junto al foso de los leones. Los cuatro pasajes restantes (Dan 7:8, 11, 20, 25) describen el cuerno de la cuarta bestia que profiere palabras arrogantes —«grandes cosas» contra el Altísimo—. La traducción española emplea consistentemente formas del verbo «hablar»: hablaba, hablando, hablará.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4455a', 'spa', 'Botín, presa o despojo tomado en guerra, especialmente los despojos de la campaña contra Madián en Números 31', 'Sustantivo masculino derivado de la raíz laqach («tomar»), que denota botín, presa o despojos capturados en conflicto militar. Casi todas sus apariciones se concentran en Números 31, el relato de la campaña israelita contra Madián, donde el término abarca el ganado, los bienes y las riquezas capturados, repartidos entre los guerreros y la congregación. Isaías 49:24-25 lo usa retóricamente, preguntando si se puede arrebatar la presa al valiente, con Dios declarando que contenderá con los opresores de Israel y rescatará a sus cautivos. El vocablo suele aparecer junto a shevi («cautivos») y shalal («despojo»), formando la tríada estándar para los frutos de la guerra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4456', 'spa', 'Lluvia tardía, lluvia de primavera; los aguaceros de marzo-abril esenciales para madurar el grano antes de la cosecha.', 'El מַלְקוֹשׁ es la lluvia tardía que cae en marzo y abril, indispensable para la maduración final de los cultivos de grano antes de la cosecha de primavera. Se empareja con el יוֹרֶה (lluvia temprana u otoñal) a lo largo de las Escrituras, marcando juntos los extremos del año agrícola de Israel (Dt 11:14; Jer 5:24; Jl 2:23). Oseas la emplea como símil de la venida fiel de Dios: «Vendrá a nosotros como la lluvia tardía» (Os 6:3). Proverbios compara el favor del rey con una «nube de lluvia tardía» (16:15). Su significado agrícola y teológico es profundamente estacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4457', 'spa', 'Tenazas o despabiladeras: sustantivo en forma dual para utensilios del templo usados para recortar mechas o manejar brasas.', 'Sustantivo en forma dual que designa las tenazas o despabiladeras utilizadas en el culto sagrado de Israel. Estos utensilios cumplían dos funciones relacionadas pero distintas: tomar brasas ardientes del altar, como en la dramática visión del templo de Isaías donde un serafín toma un carbón encendido con tenazas (Is 6:6), y recortar las mechas del candelabro de oro en el tabernáculo y el templo (Ex 25:38; 37:23; Nm 4:9; 1 R 7:49; 2 Cr 4:21). La forma dual (melqachayim) refleja los dos brazos del instrumento, semejante a unas pinzas o tenacillas modernas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4462', 'spa', 'Memucán, príncipe persa y consejero del rey Asuero', 'Uno de los siete príncipes de Persia y Media que tenían acceso al rey Asuero (Jerjes) y ocupaban los puestos más altos del reino (Ester 1:14). Cuando la reina Vasti se negó a acudir al llamado del rey, Memucán propuso el decreto que la depuso y estableció la ley de que todo hombre debía gobernar en su propia casa (Ester 1:16-21). Su consejo, motivado por el temor de que la desobediencia de Vasti inspirara una rebelión generalizada entre las esposas, desencadenó los acontecimientos que llevaron a Ester al trono.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4465', 'spa', 'Venta o transacción de bienes; también la mercancía o los artículos que se venden', 'Sustantivo derivado de la raíz makar (''vender'') que se refiere principalmente al acto de vender, especialmente a las transacciones de tierras reguladas por la legislación del Jubileo. En Levítico 25, el término aparece repetidamente en el contexto de los derechos de redención de propiedades, según los cuales lo vendido debe regresar eventualmente a su dueño original. También puede referirse de manera concreta a la mercancía misma, como cuando Nehemías confrontó a los comerciantes que traían sus productos para vender en sábado (Neh 13:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4467', 'spa', 'Reino, dominio; también el ejercicio abstracto de la realeza, la soberanía real o el señorío.', 'Mamlajá designa tanto el territorio concreto sobre el que gobierna un rey como la autoridad abstracta del oficio real. La gran mayoría de sus 117 apariciones se refieren a reinos o dominios específicos, desde el dominio fundacional de Nimrod en Génesis 10:10 hasta las monarquías divididas de Israel y Judá. Las traducciones convergen de modo notable: inglés kingdom, español reino, francés royaume, alemán Königreich. Un grupo reducido pero importante, concentrado en Crónicas y Jeremías, se desplaza hacia el sentido abstracto de realeza o dominio real: el derecho y el poder de reinar, más que la tierra misma. Éxodo 19:6 —«reino de sacerdotes»— abarca bellamente ambos sentidos: Israel como dominio de Dios y como pueblo que ejerce soberanía sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4468', 'spa', 'Reino, reinado o dominio real; el territorio o la autoridad soberana del gobierno de un rey.', 'Este sustantivo femenino es una variante de la más frecuente mamlakhah y designa un reino, dominio o reinado. La mayoría de sus apariciones se concentran en Josué 13, donde describe los reinos de los gobernantes transjordanos Og y Sijón, territorios asignados a las tribus orientales de Israel. En 1 Samuel 15:28, Samuel anuncia dramáticamente que Yahvé ha arrancado el reinado de Israel de las manos de Saúl. Oseas 1:4 profetiza que Dios pondrá fin al reino de la casa de Israel, y Jeremías 26:1 lo emplea temporalmente: ''al comienzo del reinado de Joacim''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4471', 'spa', 'Mamre — nombre personal y lugar cercano a Hebrón, asociado con la morada y el sepulcro de Abraham', 'Mamre funciona como nombre personal y como topónimo en Génesis, siempre vinculado a la historia de Abraham. Como lugar, designa los ''encinos de Mamre'' cerca de Hebrón, donde Abraham se asentó (Gn 13:18), recibió a los tres visitantes que anunciaron el nacimiento de Isaac (18:1), y donde se encontraba la cueva sepulcral de Macpela (23:17, 19; 25:9; 49:30; 50:13). Como persona, Mamre es un aliado amorreo de Abraham en la campaña contra los cuatro reyes (Gn 14:13, 24). La Septuaginta lo traduce consistentemente como Mambrē, y las principales tradiciones de traducción conservan el nombre sin alteraciones, reflejando su arraigo en la geografía patriarcal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4474', 'spa', 'dominio, autoridad soberana; también concretamente, gobernantes', 'Este sustantivo designa el ejercicio de autoridad soberana o dominio, y por extensión puede referirse concretamente a quienes detentan dicho poder. En Daniel 11:3, un rey poderoso se levanta y gobierna con «gran dominio», y en 11:5 el término describe el alcance de la autoridad de un gobernante. El uso concreto en plural en 1 Crónicas 26:6 designa a los «gobernantes» o líderes dentro del clan de Obed-edom. Las traducciones españolas reflejan bien ambas facetas: «dominio» para lo abstracto y «gobernantes» para lo concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4475', 'spa', 'Dominio, gobierno, reino — autoridad soberana o jurisdicción ejercida por Dios, reyes o cuerpos celestes.', 'Dominio, gobierno, reino — autoridad soberana o jurisdicción ejercida por Dios, reyes o cuerpos celestes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4478a', 'spa', 'Maná — la sustancia milagrosa semejante al pan que Dios proveyó diariamente durante la peregrinación de Israel por el desierto.', 'Maná — la sustancia milagrosa semejante al pan que Dios proveyó diariamente durante la peregrinación de Israel por el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4479', 'spa', '¿Quién? quienquiera — pronombre interrogativo e indefinido relativo en arameo, usado en Esdras y Daniel', 'Este es el equivalente arameo del hebreo mî, que funciona tanto como pronombre interrogativo (''¿quién?'') como pronombre relativo indefinido (''quienquiera''). Aparece exclusivamente en las secciones arameas de Esdras y Daniel. El desafío de Nabucodonosor man-hûʾ ʾĕlāh (''¿quién es el dios que...?'' Dan 3:15) constituye uno de sus usos más impactantes, mientras que la forma compuesta man-dî genera el indefinido ''quienquiera'' en decretos reales (Dan 3:6, 11; 5:7; 6:8). El pronombre pertenece a una amplia familia semítica — siríaco man, árabe man, arameo antiguo mn — todos descendientes de una raíz interrogativa común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4480', 'spa', 'de, desde, parte de (forma preposicional aramea usada con sufijos pronominales)', 'Esta forma preposicional aramea significa «de», «desde» o «parte de», y aparece tanto en lecturas Qeré como en variantes Ketiv. En Daniel 2:41-42 describe la composición mixta de los pies de la estatua —en parte fuerte, en parte frágil—, mientras que en Job 38:1 y 40:6 introduce los discursos divinos «desde» el torbellino. Las traducciones multilingües reflejan su fuerza partitiva y ablativa: el español la vierte como «de» y «parte de ellos», captando el matiz de procedencia y composición parcial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4480a', 'spa', 'De, desde, fuera de; también comparativo ''más que'', partitivo ''algo de'' y causal ''a causa de, por motivo de''', 'La preposición מִן es una de las palabras funcionales más fundamentales del hebreo bíblico, que expresa la idea nuclear de separación u origen: ''de'', ''desde'', ''fuera de''. Con más de 1200 apariciones solo en este subconjunto flexivo, es el marcador primario de procedencia y alejamiento en la lengua. Pero מִן va mucho más allá de lo espacial: su rango semántico se extiende a la comparación (''más que'', el llamado מִן comparativo), la partición (''algo de'', el מִן partitivo) e incluso la causalidad (''a causa de''). Estos sentidos secundarios no son meros matices contextuales, sino funciones gramaticales genuinas reconocidas por todas las gramáticas hebreas desde los gramáticos medievales. Los cognados semíticos —árabe min, arameo min, etiópico ''em— confirman que esta polisemia es antigua y heredada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4481', 'spa', 'Preposición aramea: de, desde, indicando origen o procedencia; también partitivo «parte de» y raramente adversativo «contra».', 'La preposición aramea min funciona como marcador principal de procedencia, separación y origen en las secciones arameas de Daniel y Esdras. Paralela a su cognado hebreo, maneja con igual soltura relaciones espaciales («desde allí», Esd 6:6), temporales («desde los días de», Esd 4:15) y causales («a causa de»). Un uso partitivo característico —«parte de ellos»— destaca en la visión de la estatua de Daniel (Dn 2:33, 41-42), donde los pies son «en parte de hierro y en parte de barro». El raro sentido adversativo («contra él», Esd 7:26) completa su campo semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4483', 'spa', 'contar, calcular; nombrar, designar (verbo arameo usado de decretos divinos y comisiones reales)', 'Este verbo arameo posee dos significados distintos pero relacionados: contar o calcular, y nombrar o designar. Su aparición más memorable se halla en la escritura en la pared: «Dios ha contado tu reino» (Dan 5:26), donde el acto de contar implica poner fin. En su sentido administrativo, Nabucodonosor «designó» funcionarios (Dan 2:24, 49; 3:12), y a Esdras se le encomendó «nombrar» jueces (Esd 7:25). Las traducciones españolas captan bien ambas vertientes: «ha contado» para el cómputo divino y «nombra» o «designó» para la asignación de cargos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4484', 'spa', 'MENE (arameo: ''contado'' o ''mina''; palabra de la escritura misteriosa en la pared)', 'Palabra aramea que aparece en la misteriosa escritura sobre la pared durante el banquete de Belsasar. «MENE» figura dos veces en la inscripción (Daniel 5:25) y recibe una sola interpretación (5:26). El término encierra un juego de palabras: puede significar «contado» (del verbo contar) o «mina» (unidad de peso). Daniel lo interpreta así: «Dios ha contado los días de tu reino y le ha puesto fin». La doble aparición subraya la certeza y la irrevocabilidad del decreto divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4486', 'spa', 'conocimiento, entendimiento (arameo)', 'Sustantivo arameo que denota conocimiento o la capacidad de comprender, presente exclusivamente en Daniel. Dios «da conocimiento a los entendidos» (Daniel 2:21), estableciéndose como fuente de toda sabiduría. Cuando Nabucodonosor recuperó la cordura tras su periodo de locura, «mi entendimiento volvió a mí» (Daniel 4:34, 36). Daniel poseía «entendimiento para interpretar sueños» (Daniel 5:12). El término enfatiza no solo el saber factual sino la facultad de comprensión, la capacidad cognitiva de discernir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4487', 'spa', 'Contar, numerar, calcular; designar, asignar o destinar; en voz pasiva, ser contado o ser designado.', 'Contar, numerar, calcular; designar, asignar o destinar; en voz pasiva, ser contado o ser designado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4488', 'spa', 'mina -- unidad de peso y valor monetario equivalente a 50 o 60 siclos, usada para medir metales preciosos', 'La mina era una unidad de peso estándar del antiguo Cercano Oriente empleada para medir metales preciosos. Equivalente a una sexagésima parte de un talento, pesaba entre 800 y 980 gramos según la época: unas dos libras conforme al patrón babilónico antiguo, o aproximadamente 1⅔ libras según el cálculo de Ezequiel de 50 siclos por mina (Ez 45:12). Los escudos de oro de Salomón requerían tres minas cada uno (1 R 10:17), mientras que los exiliados que regresaron donaron minas de plata para la reconstrucción del templo (Esd 2:69; Neh 7:71-72). Todas las traducciones principales la vierten de forma consistente como ''minas.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4490', 'spa', 'Porción, parte; una ración asignada de alimento o sacrificio, especialmente un trozo escogido dado como regalo u ofrenda.', 'Porción, parte; una ración asignada de alimento o sacrificio, especialmente un trozo escogido dado como regalo u ofrenda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4494', 'spa', 'Reposo, descanso (estado abstracto de seguridad y paz); lugar de descanso (sitio concreto de morada estable o aterrizaje).', 'El sustantivo manoach designa tanto la condición de reposo como el lugar donde se halla ese descanso, dualidad semántica familiar por el emparentado menuchah, aunque aparece solo seis veces. En sentido abstracto, nombra la seguridad que viene al cesar de vagar: Noemí busca «reposo» para Rut mediante el matrimonio (Rut 3:1) y el salmista dice «vuelve a tu reposo, alma mía» (Sal 116:7). En sentido concreto, designa un lugar físico: la paloma de Noé no halló «lugar de descanso» para su pie (Gn 8:9) y las maldiciones del pacto amenazan con que Israel no hallará reposo en el exilio (Dt 28:65).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4495', 'spa', 'Manoa: padre de Sansón, de la tribu de Dan. Nombre propio masculino que significa ''descanso'' o ''lugar de reposo'', derivado de la raíz נוח. Manoa era u', 'Manoa: padre de Sansón, de la tribu de Dan. Nombre propio masculino que significa ''descanso'' o ''lugar de reposo'', derivado de la raíz נוח. Manoa era un danita de la ciudad de Zora cuya esposa recibió el anuncio angélico del nacimiento de Sansón (Jue 13:2-22). Se lo retrata como un hombre devoto pero cauteloso que ora para volver a ver al ángel y ofrece un sacrificio sobre el cual el ángel asciende en la llama (Jue 13:19-20). Su reacción alarmada — ''ciertamente moriremos, porque hemos visto a Dios'' — es corregida con suavidad por su esposa, más perceptiva (Jue 13:22-23). Sansón es sepultado en la tumba de su padre, entre Zora y Estaol (Jue 16:31). La Septuaginta traduce su nombre como Μανωε.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4496', 'spa', 'Descanso, reposo, tranquilidad; también lugar de reposo o morada establecida, especialmente para Dios o su pueblo.', 'Descanso, reposo, tranquilidad; también lugar de reposo o morada establecida, especialmente para Dios o su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4498', 'spa', 'Refugio, lugar de escape; huida, el acto de escapar.', 'El sustantivo מָנוֹס (manos), de la raíz נוּס (''huir''), posee dos significados orgánicamente conectados: el destino al que se huye y el acto mismo de huir. En la mayoría de sus ocho apariciones designa un refugio o lugar de seguridad, aplicado supremamente a Dios como «mi refugio» en el salmo de liberación de David (2 S 22:3) y en la confesión de Jeremías (Jer 16:19). Cuando el refugio «perece» o «se pierde», la palabra transmite desesperación (Am 2:14; Job 11:20). En Jer 46:5 y Am 2:14, cobra relieve el acto concreto de la huida cuando los ejércitos escapan sin hallar refugio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4500', 'spa', 'enjulio del telar (vara cilíndrica del telar)', 'La vara gruesa de madera del telar que sostiene los hilos de la urdimbre, utilizada en las Escrituras exclusivamente en símiles que describen astas de lanza de gran tamaño. El asta de la lanza de Goliat era «como un enjulio de tejedor» (1 Samuel 17:7), al igual que las armas de otros gigantes filisteos (2 Samuel 21:19, 1 Crónicas 11:23, 20:5). La comparación evoca tanto grosor como peso: no eran lanzas comunes, sino armas que requerían una fuerza extraordinaria para blandirlas, a la medida de los guerreros descomunales que las portaban.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4501', 'spa', 'Candelabro, menorá; el candelabro dorado de siete brazos del Tabernáculo/Templo, o un candelero doméstico', 'Candelabro, menorá; el candelabro dorado de siete brazos del Tabernáculo/Templo, o un candelero doméstico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4503', 'spa', 'Don, tributo, ofrenda; desde regalos seculares entre personas, pasando por tributo vasallático, hasta la ofrenda de grano del culto levítico.', 'Minjá traza un arco semántico fascinante desde lo cotidiano hasta lo sagrado. En sus usos narrativos más antiguos significa simplemente un regalo: el presente de Jacob a Esaú (Gn 32:14), el obsequio de los hermanos a José (Gn 43:11). En contextos políticos se estrecha a tributo: el pago obligatorio que un vasallo lleva a su señor, como el tributo de Ehud a Eglón (Jue 3:15). Pero en la literatura sacerdotal se convierte en el término técnico por excelencia para la ofrenda de grano descrita en Levítico 2, compuesta de flor de harina mezclada con aceite e incienso. La evidencia árabe es particularmente reveladora: los usos seculares activan hadiyya («regalo»), los políticos jizya o kharaj («tributo»), y los cultuales taqdima («presentación formal»), tres palabras árabes distintas para lo que el hebreo cubre con una sola. Esta polisemia estratificada conserva la intuición teológica de que la adoración es, en su nivel más profundo, un acto de dar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4505', 'spa', 'Menahem — nombre propio que significa ''consolador''; rey del reino del norte de Israel (2 Reyes 15).', 'Nombre propio hebreo que significa «consolador» o «el que consuela», derivado de la raíz נחם (najam, ''consolar''). Menahem hijo de Gadí usurpó el trono de Israel asesinando a Salum y reinó diez años en Samaria (2 R 15:14-23). Su gobierno se caracterizó por la represión brutal de la oposición y un pesado tributo pagado a Tiglat-pileser III de Asiria. La Septuaginta griega lo transcribe como Μαναημ (Manaem), conservando la he gutural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4509', 'spa', 'Miniamín/Minyamín (nombre propio: posiblemente ''de la mano derecha'' o ''afortunado'')', 'Nombre propio con múltiples variantes ortográficas, llevado por individuos de linaje sacerdotal en contextos postexílicos. Un Miniamín sirvió durante las reformas de Ezequías, ayudando a distribuir las porciones sacerdotales (2 Crónicas 31:15). Otros aparecen entre los sacerdotes que regresaron con Zorobabel y sirvieron en tiempos de Nehemías (Nehemías 12:17, 41). Las variaciones en la grafía reflejan diferencias escribales o posiblemente individuos distintos con nombres similares. Todas las ocurrencias involucran servicio sacerdotal y ministerio en el templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4513', 'spa', 'Retener, impedir, contener; en Nifal, ser retenido o impedido de ocurrir.', 'Retener, impedir, contener; en Nifal, ser retenido o impedido de ocurrir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4514', 'spa', 'Cerradura, cerrojo o tranca: dispositivo de cierre para asegurar puertas y portones de la ciudad.', 'Sustantivo masculino que designa una cerradura, cerrojo o tranca empleada para asegurar puertas o portones. Cinco de sus seis apariciones se concentran en Nehemías 3 (vv. 3, 6, 13, 14, 15), donde la fórmula repetida «sus puertas, sus cerraduras y sus barras» describe la reconstrucción sistemática de las puertas de Jerusalén. Su única otra aparición se halla en Cantares 5:5, donde los dedos de la amada destilan mirra sobre el cerrojo de la puerta, una imagen notablemente íntima. El vocablo evoca seguridad y clausura, ya sea cívica o personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4518', 'spa', 'tazones o jarros (para uso sagrado)', 'Vasijas asociadas con el servicio del tabernáculo y del templo, mencionadas en las descripciones del mobiliario sagrado. Aparecen entre los utensilios de la mesa de los panes de la proposición (Éxodo 25:29, 37:16) y los recipientes empleados para transportar el pan durante los viajes por el desierto (Números 4:7). El término también figura en el inventario de los utensilios del templo llevados a Babilonia y posteriormente devueltos (Jeremías 52:19). No eran vasijas comunes, sino implementos santificados reservados para fines litúrgicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4519', 'spa', 'Manasés; el primogénito de José, sus descendientes tribales, su territorio, o personas posteriores con ese nombre.', 'Derivado del verbo נָשָׁה («olvidar»), el nombre de Manasés se explica en Génesis 41:51: «Dios me ha hecho olvidar todas mis penalidades». Como nombre propio abarca al patriarca individual (Gn 46:20; 48:1-20), la poderosa media tribu repartida entre los territorios de Transjordania y Cisjordania (Jos 17; Nm 32) y figuras posteriores, incluido el tristemente célebre rey Manasés de Judá (2 Re 21). La forma gentilicia «el manasita» (הַמְנַשִּׁי) aparece una vez en 1 Crónicas 27:21 para designar a un miembro de la tribu, mostrando la capacidad productiva del nombre como gentilicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4520', 'spa', 'Manasita (gentilicio), perteneciente a la tribu de Manasés', 'Adjetivo gentilicio que identifica a los miembros o el territorio de la tribu de Manasés, particularmente la media tribu que se estableció al este del Jordán. Aparece en la designación de ciudades de refugio (Deuteronomio 4:43), descripciones territoriales (2 Reyes 10:33), genealogías tribales y divisiones administrativas (1 Crónicas 26:32). El término distinguía a los manasitas transjordanos de sus contrapartes occidentales, reflejando la división tribal producida cuando parte de Manasés optó por establecerse en Galaad y Basán en lugar de cruzar a la tierra de Canaán propiamente dicha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4521', 'spa', 'Porción, asignación o parte designada, especialmente de ofrendas, provisiones, o figuradamente del juicio o bendición divina.', 'Sustantivo femenino en estado constructo estrechamente relacionado con מָנָה, que designa una porción o parte asignada. En Crónicas y Nehemías se refiere a las porciones prescritas para sacerdotes, levitas y cantores provenientes de la contribución real para los sacrificios (2 Cr 31:3-4; Neh 12:44, 47; 13:10). En sentido figurado, expresa lo que Dios asigna: en el Salmo 11:6 «la porción de su copa» es el destino de los impíos, mientras que en el Salmo 16:5 el SEÑOR mismo es «la porción de mi herencia y mi copa», una de las expresiones más íntimas de devoción personal en el Salterio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4522', 'spa', 'Trabajo forzado, corvea; más tarde, tributo monetario o leva de impuestos sobre pueblos sometidos.', 'Trabajo forzado, corvea; más tarde, tributo monetario o leva de impuestos sobre pueblos sometidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4524', 'spa', 'alrededores, en derredor; mesa redonda o diván; entorno que circunda', 'Derivado de la raíz que significa ''rodear,'' este sustantivo describe lo que circunda o envuelve, ya sean los lugares en torno a Jerusalén (2 R 23:5), las paredes talladas decoradas ''alrededor'' (1 R 6:29), las nubes girando en toda dirección (Job 37:12) o los enemigos que cercan al salmista (Sal 140:9). Su aparición más debatida es Cnt 1:12, donde ''mientras el rey estaba en su mesab'' se ha interpretado como una mesa redonda, un diván de banquete o simplemente su círculo de acompañantes. El español ''en su mesa'' y el francés ''dans son festin'' reflejan la lectura del banquete.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4525', 'spa', 'Herrero o cerrajero (artesano deportado con la elite de Judá); también calabozo o prisión (lugar donde se encierra).', 'Derivado de la raíz סָגַר (sagar, ''cerrar, clausurar''), este sustantivo se bifurca en dos aplicaciones concretas. Como término artesanal, מַסְגֵּר designa a los herreros o cerrajeros deportados de Jerusalén por Nabucodonosor junto con los חָרָשׁ (artesanos): «todos los artesanos y los herreros» (2 R 24:14, 16; Jer 24:1; 29:2). Como lugar de confinamiento, significa calabozo o prisión: «saca mi alma de la cárcel» (Sal 142:7), «para sacar a los presos del calabozo» (Is 42:7). En el juicio escatológico de Isaías 24:22, los cautivos son reunidos «en la prisión».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4526', 'spa', 'Borde, marco o panel (en mobiliario sagrado); también fortaleza o baluarte. מִסְגֶּרֶת es un sustantivo derivado de la raíz סגר (''cerrar, encerrar''), ', 'Borde, marco o panel (en mobiliario sagrado); también fortaleza o baluarte. מִסְגֶּרֶת es un sustantivo derivado de la raíz סגר (''cerrar, encerrar''), y sus significados reflejan diferentes tipos de cerramiento. En las instrucciones del tabernáculo (Éx 25), designa el marco decorativo que rodea la mesa de los panes de la proposición, mientras que en el templo de Salomón el plural describe los paneles ornamentados de las bases de bronce (1 R 7:28-36). Un tercer sentido completamente distinto emerge en textos poéticos: la fortaleza o baluarte de donde las naciones salen temblando ante Dios (2 S 22:46; Mi 7:17), preservando la idea raíz de un lugar cerrado, pero ahora aplicada a fortificaciones defensivas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4529', 'spa', 'Derretir, disolver, hacer fluir', 'Verbo en forma Hifil que significa causar la disolución o el derretimiento de algo, empleado tanto literal como metafóricamente. Dios derrite el hielo con su palabra (Salmo 147:18), demostrando su poder sobre la naturaleza. Las lágrimas del salmista «disuelven» su lecho (Salmo 6:7), y la reprensión divina «consume» lo preciado como polilla (Salmo 39:11). También describe el efecto de hacer que el corazón de alguien se «derrita» de miedo, es decir, intimidarlo hasta hacerle perder el valor (Josué 14:8). La imagen constante es la reducción de lo sólido a lo líquido, de lo firme a lo inestable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4531b', 'spa', 'Masá, lugar de prueba en el desierto; o pruebas/tentaciones', 'Nombre dado a un lugar en el desierto donde Israel puso a prueba al Señor al dudar de su presencia y provisión (Éxodo 17:7, Deuteronomio 6:16, 9:22), frecuentemente emparejado con Meriba («contienda»). El nombre significa «prueba» o «tentación», y el Salmo 95:8 lo usa como advertencia contra endurecer el corazón como lo hizo la generación del desierto. Deuteronomio 33:8 menciona también la prueba de Leví «en Masá». En algunos contextos funciona como sustantivo común que designa las pruebas que Dios infligió sobre Egipto (Deuteronomio 4:34, 7:19, 29:3). El topónimo se convirtió en sinónimo de la tentación de poner a prueba la fidelidad de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4532', 'spa', 'Masá, lugar en el desierto donde Israel puso a prueba a Dios', 'Nombre geográfico que señala el sitio donde los israelitas pusieron a prueba al Señor exigiendo agua y cuestionando su presencia entre ellos (Éxodo 17:7). Moisés llamó al lugar Masá («prueba») y Meriba («contienda») para dejar memoria perpetua de la infidelidad de Israel. Las Escrituras posteriores lo citan como advertencia contra repetir la falta de confianza de la generación del desierto (Deuteronomio 6:16, 9:22, Salmo 95:8). Deuteronomio 33:8 menciona que Dios probó a Leví «en Masá», posiblemente aludiendo a múltiples incidentes en el lugar o vinculándolo con las pruebas de consagración levítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4533', 'spa', 'Velo, cobertura para el rostro', 'Sustantivo que designa un velo o cobertura facial, presente únicamente en el relato del descenso de Moisés del monte Sinaí. Tras hablar con Dios, el rostro de Moisés resplandecía con tal intensidad que se colocó un velo al dirigirse al pueblo (Éxodo 34:33, 35). Lo retiraba al entrar en la presencia de Dios (34:34). El velo mediaba entre la gloria divina reflejada en el rostro de Moisés y la incapacidad del pueblo para soportar ese resplandor, prefigurando reflexiones teológicas posteriores sobre la revelación velada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4537', 'spa', 'mezclar, combinar; verter o preparar (vino con especias, o bebida con lágrimas)', 'Verbo que describe el arte de combinar bebidas, ya sea mezclando vino con especias aromáticas para lograr un brebaje más rico, o mezclando la propia bebida con lágrimas de aflicción. La Sabiduría personificada ''ha mezclado su vino'' al preparar su mesa de banquete (Pr 9:2, 5), convirtiendo este verbo en símbolo tanto de hospitalidad como de invitación divina. En un registro más sombrío, el SEÑOR ''ha derramado sobre Egipto un espíritu de confusión'' (Is 19:14), extendiendo la metáfora de la mezcla al juicio divino. El lamento del salmista -- ''mezclo mi bebida con llanto'' (Sal 102:9) -- es una de las imágenes más vívidas de la Escritura sobre una vida cotidiana empapada de dolor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4539', 'spa', 'Pantalla, cortina o cubierta; un colgante usado como separación en el Tabernáculo o una cubierta protectora en contextos más amplios.', 'Pantalla, cortina o cubierta; un colgante usado como separación en el Tabernáculo o una cubierta protectora en contextos más amplios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4541a', 'spa', 'Imagen fundida/de fundición (ídolo); raramente, libación o cubierta derramada en la formación de alianzas.', 'Imagen fundida/de fundición (ídolo); raramente, libación o cubierta derramada en la formación de alianzas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4542', 'spa', 'Pobre, necesitado (probablemente un préstamo lingüístico)', 'Adjetivo que describe la pobreza, aparece exclusivamente en Eclesiastés. El «joven pobre y sabio» supera al rey viejo y necio (Eclesiastés 4:13). Un hombre pobre y sabio libró a su ciudad con sabiduría, pero después fue olvidado (Eclesiastés 9:15-16). El término probablemente ingresó al hebreo como préstamo del acadio (muškênu, «mendigo»), lo que sugiere que podía conllevar matices de clase social o estatus legal más allá de la simple pobreza económica. Eclesiastés lo utiliza para resaltar la paradoja de que la sabiduría en un hombre pobre es menospreciada a pesar de su eficacia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4543', 'spa', 'Almacenes o ciudades de aprovisionamiento — depósitos fortificados para grano, provisiones y pertrechos militares', 'Sustantivo femenino plural que designa instalaciones de almacenamiento o ciudades de aprovisionamiento donde se acumulaban provisiones, grano y recursos militares. El término aparece casi exclusivamente en la expresión ''arei ha-miskenot'' (ciudades de almacenaje). Incluye las ciudades que Faraón obligó a Israel a construir (Éx 1:11), los depósitos de Salomón a lo largo de su reino (1 R 9:19; 2 Cr 8:4, 6) y los almacenes fortificados de Josafat (2 Cr 17:12). La evidencia multilingüe es notablemente uniforme: todas las tradiciones coinciden en señalar infraestructura de almacenamiento construida con un propósito específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4546', 'spa', 'Calzada, camino elevado — una vía preparada para el tránsito; raramente escalera o curso celestial', 'Calzada, camino elevado — una vía preparada para el tránsito; raramente escalera o curso celestial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4548', 'spa', 'clavo (para sujetar o asegurar materiales)', 'Clavos o espigas de metal utilizados para sujetar y unir materiales. David preparó clavos de hierro para el templo (1 Crónicas 22:3), y clavos de oro aseguraban el revestimiento del Lugar Santísimo (2 Crónicas 3:9). Isaías se burla de los fabricantes de ídolos que aseguran a sus dioses con clavos para que no se tambaleen (Isaías 41:7), y Jeremías describe ídolos «fijados con clavos y martillos» (Jeremías 10:4). Eclesiastés emplea los clavos como metáfora de dichos de sabiduría firmemente arraigados (Eclesiastés 12:11).');